INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Sinigang na Baboy', 'Soup/Stew', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "pork ribs, cut into serving pieces", "description": "150g pork ribs, cut into serving pieces", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_PORK_RIBS"}, {"name": "medium tomato, quartered", "description": "1/2 medium tomato, quartered", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_TOMATO"}, {"name": "medium onion, quartered", "description": "1/4 medium onion, quartered", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "siling haba", "description": "1/2 pc siling haba", "amount": "1/2 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_HABA"}, {"name": "medium radish, sliced", "description": "1/4 medium radish, sliced", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_RADISH"}, {"name": "medium eggplant, sliced", "description": "1/4 medium eggplant, sliced", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_EGGPLANT"}, {"name": "kangkong, stems trimmed", "description": "1/4 bundle kangkong, stems trimmed", "amount": "1/4 bundle", "market_section": "Vegetable Section", "product_key": "VEG_KANGKONG"}, {"name": "sinigang mix or 30g fresh tamarind", "description": "10g sinigang mix or 30g fresh tamarind", "amount": "10g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SINIGANG_MIX_FRESH"}, {"name": "water", "description": "500ml water", "amount": "500ml", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WATER"}, {"name": "fish sauce, or to taste", "description": "1 tbsp fish sauce, or to taste", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE"}]'::jsonb, '[{"title": "Step 1", "description": "In a large pot, bring 2 liters of water to a boil. Add pork ribs and blanch for 5 minutes. Discard water and rinse pork."}, {"title": "Step 2", "description": "Return pork to pot with fresh 2 liters water. Add tomatoes and onion. Boil then simmer for 45-60 minutes until pork is fork-tender."}, {"title": "Step 3", "description": "Skim scum regularly for a clear broth."}, {"title": "Step 4", "description": "Add tamarind mix or strained fresh tamarind juice. Stir and taste."}, {"title": "Step 5", "description": "Add radish and eggplant. Simmer 5 minutes."}, {"title": "Step 6", "description": "Add siling haba and kangkong. Cook 2 minutes more."}, {"title": "Step 7", "description": "Season with fish sauce. Serve hot with steamed rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Adobong Manok', 'Braised', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '650 kcal', 4292932350, '[{"name": "chicken, preferably bone-in thigh or drumstick", "description": "150g chicken, preferably bone-in thigh or drumstick", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_CHICKEN"}, {"name": "vinegar", "description": "2 tbsp vinegar", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_VINEGAR"}, {"name": "soy sauce", "description": "1 tbsp soy sauce", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "cloves garlic, crushed", "description": "3 cloves garlic, crushed", "amount": "3", "market_section": "Vegetable Section", "product_key": "VEG_CLOVES_GARLIC"}, {"name": "bay leaf", "description": "1 pc bay leaf", "amount": "1 pc", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BAY_LEAF"}, {"name": "whole black peppercorns", "description": "1/4 tsp whole black peppercorns", "amount": "1/4 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WHOLE_BLACK_PEPPERCORNS"}, {"name": "water", "description": "1/4 cup water", "amount": "1/4 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WATER"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Combine chicken, vinegar, soy sauce, garlic, bay leaves, and peppercorns in a pot. Marinate 30 minutes to 1 hour."}, {"title": "Step 2", "description": "Add water. Bring to a boil over medium-high heat without stirring."}, {"title": "Step 3", "description": "Once boiling, lower heat and simmer for 25-30 minutes until chicken is tender."}, {"title": "Step 4", "description": "Remove chicken and pan-fry in hot oil until golden brown."}, {"title": "Step 5", "description": "Return to pot and reduce remaining sauce until thick and glossy."}, {"title": "Step 6", "description": "Serve with steamed rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Kare-Kare', 'Soup/Stew', '40 min', 'Hard', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1050 kcal', 4292932350, '[{"name": "oxtail", "description": "150g oxtail", "amount": "150g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_OXTAIL"}, {"name": "banana blossom", "description": "100g banana blossom", "amount": "100g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BANANA_BLOSSOM"}, {"name": "medium eggplant", "description": "1/4 medium eggplant", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_EGGPLANT"}, {"name": "sitaw", "description": "60g sitaw", "amount": "60g", "market_section": "Vegetable Section", "product_key": "VEG_SITAW"}, {"name": "peanut butter", "description": "1 tbsp peanut butter", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_PEANUT_BUTTER"}, {"name": "ground toasted peanuts", "description": "1 tbsp ground toasted peanuts", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_GROUND_TOASTED_PEANUTS"}, {"name": "annatto powder dissolved in 1/4 cup water", "description": "1 tsp annatto powder dissolved in 1/4 cup water", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_ANNATTO_POWDER_DISSOLVED"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "fish sauce", "description": "1 tsp fish sauce", "amount": "1 tsp", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE"}, {"name": "Salt to taste", "description": "Salt to taste", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_TASTE"}, {"name": "bagoong alamang, for serving", "description": "1 tbsp bagoong alamang, for serving", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_BAGOONG_ALAMANG"}]'::jsonb, '[{"title": "Step 1", "description": "Pressure cook oxtail with enough water for 45 minutes or boil for 2-3 hours until very tender. Reserve broth (at least 4 cups)."}, {"title": "Step 2", "description": "In a large pot, sauté garlic and onion in oil until soft."}, {"title": "Step 3", "description": "Add the annatto water; stir and cook 2 minutes."}, {"title": "Step 4", "description": "Add peanut butter and ground peanuts. Stir well."}, {"title": "Step 5", "description": "Pour in reserved oxtail broth. Bring to simmer."}, {"title": "Step 6", "description": "Add oxtail. Simmer 10 minutes."}, {"title": "Step 7", "description": "Add eggplant, banana blossom, and sitaw. Cook until vegetables are tender, about 8-10 minutes."}, {"title": "Step 8", "description": "Season with fish sauce and salt. Sauce should be thick and creamy."}, {"title": "Step 9", "description": "Serve with a generous side of sautéed bagoong alamang."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Lechon Kawali', 'Grilled/Fried', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1420 kcal', 4292932350, '[{"name": "pork belly slab", "description": "180g pork belly slab", "amount": "180g", "market_section": "Meat Section", "product_key": "MEAT_PORK_BELLY_SLAB"}, {"name": "salt", "description": "1/2 tsp salt", "amount": "1/2 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT"}, {"name": "black pepper", "description": "1/4 tsp black pepper", "amount": "1/4 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BLACK_PEPPER"}, {"name": "bay leaf", "description": "1 pc bay leaf", "amount": "1 pc", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BAY_LEAF"}, {"name": "cloves garlic, crushed", "description": "2 cloves garlic, crushed", "amount": "2", "market_section": "Vegetable Section", "product_key": "VEG_CLOVES_GARLIC"}, {"name": "Water for boiling", "description": "Water for boiling", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WATER_FOR_BOILING"}, {"name": "Oil for deep-frying", "description": "Oil for deep-frying", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_OIL_FOR_DEEP"}]'::jsonb, '[{"title": "Step 1", "description": "Place pork belly in a pot. Cover with water. Add salt, pepper, bay leaves, and garlic."}, {"title": "Step 2", "description": "Boil then simmer for 45-60 minutes until pork is very tender (fork goes through easily)."}, {"title": "Step 3", "description": "Remove pork; cool to room temperature."}, {"title": "Step 4", "description": "Refrigerate uncovered overnight (or at least 4 hours) — this dries the skin for maximum crispiness."}, {"title": "Step 5", "description": "Heat oil to 180°C in a deep pot or kawali."}, {"title": "Step 6", "description": "Carefully lower pork into hot oil. Fry 15-20 minutes until deep golden and very crispy."}, {"title": "Step 7", "description": "Drain on wire rack (not paper towels — steam makes skin soggy)."}, {"title": "Step 8", "description": "Rest 5 minutes before chopping. Serve with liver sauce or spiced vinegar."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tinolang Manok', 'Soup/Stew', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '520 kcal', 4292932350, '[{"name": "chicken pieces", "description": "150g chicken pieces", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_CHICKEN_PIECES"}, {"name": "green papaya, peeled and sliced", "description": "150g green papaya, peeled and sliced", "amount": "150g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_GREEN_PAPAYA"}, {"name": "malunggay leaves", "description": "1/2 cup malunggay leaves", "amount": "1/2 cup", "market_section": "Vegetable Section", "product_key": "VEG_MALUNGGAY_LEAVES"}, {"name": "1-inch ginger, julienned", "description": "1-inch ginger, julienned", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_INCH_GINGER"}, {"name": "medium onion, sliced", "description": "1/4 medium onion, sliced", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "garlic, minced", "description": "1 clove garlic, minced", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "fish sauce", "description": "1 tbsp fish sauce", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE"}, {"name": "water", "description": "500ml water", "amount": "500ml", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WATER"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil in pot over medium heat. Sauté ginger until fragrant, about 1 minute."}, {"title": "Step 2", "description": "Add garlic and onion; cook until soft."}, {"title": "Step 3", "description": "Add chicken pieces. Cook, turning, until lightly browned on all sides."}, {"title": "Step 4", "description": "Pour in water. Bring to a boil; skim scum."}, {"title": "Step 5", "description": "Add green papaya. Simmer 15-20 minutes until papaya and chicken are tender."}, {"title": "Step 6", "description": "Season with fish sauce."}, {"title": "Step 7", "description": "Add malunggay leaves. Cook 1 minute more."}, {"title": "Step 8", "description": "Serve hot with rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Bistek Tagalog', 'Braised', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1030 kcal', 4292932350, '[{"name": "beef sirloin or round, thinly sliced", "description": "150g beef sirloin or round, thinly sliced", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_BEEF_SIRLOIN_ROUND"}, {"name": "calamansi juice", "description": "1 1/2 tbsp calamansi juice", "amount": "1 1/2 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_CALAMANSI_JUICE"}, {"name": "soy sauce", "description": "1 tbsp soy sauce", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "medium onion, sliced into rings", "description": "1/2 medium onion, sliced into rings", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "garlic, minced", "description": "1 clove garlic, minced", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "black pepper", "description": "1/8 tsp black pepper", "amount": "1/8 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BLACK_PEPPER"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Salt to taste", "description": "Salt to taste", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_TASTE"}]'::jsonb, '[{"title": "Step 1", "description": "Marinate beef in calamansi juice, soy sauce, garlic, and black pepper for at least 30 minutes."}, {"title": "Step 2", "description": "Heat oil in pan over high heat. Sear beef slices quickly, about 1 minute per side. Remove and set aside."}, {"title": "Step 3", "description": "In same pan, cook onion rings until slightly softened and lightly caramelized."}, {"title": "Step 4", "description": "Return beef to pan with marinade. Simmer 2-3 minutes until sauce slightly thickens."}, {"title": "Step 5", "description": "Taste and adjust — add more calamansi for sourness, soy for saltiness."}, {"title": "Step 6", "description": "Serve over steamed rice, topped with onion rings."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pork Dinuguan', 'Soup/Stew', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1850 kcal', 4292932350, '[{"name": "pork shoulder, cubed", "description": "150g pork shoulder, cubed", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_PORK_SHOULDER"}, {"name": "pork intestine, cleaned and cut", "description": "75g pork intestine, cleaned and cut", "amount": "75g", "market_section": "Meat Section", "product_key": "MEAT_PORK_INTESTINE"}, {"name": "fresh pork blood", "description": "1/4 cup fresh pork blood", "amount": "1/4 cup", "market_section": "Meat Section", "product_key": "MEAT_FRESH_PORK_BLOOD"}, {"name": "vinegar", "description": "1 1/2 tbsp vinegar", "amount": "1 1/2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_VINEGAR"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "siling haba", "description": "1 pc siling haba", "amount": "1 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_HABA"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Fish sauce and salt to taste", "description": "Fish sauce and salt to taste", "amount": "1 serving", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE_AND"}]'::jsonb, '[{"title": "Step 1", "description": "Boil pork intestines in water with garlic and vinegar for 30 minutes until tender. Drain and cut."}, {"title": "Step 2", "description": "In a pot, heat oil and sauté garlic and onion until fragrant."}, {"title": "Step 3", "description": "Add pork shoulder; cook until browned."}, {"title": "Step 4", "description": "Add intestines; stir."}, {"title": "Step 5", "description": "Pour in pork blood. Stir constantly while bringing to a simmer to prevent lumps."}, {"title": "Step 6", "description": "Add vinegar; do not stir for 2 minutes (let it cook off)."}, {"title": "Step 7", "description": "Add siling haba. Simmer 15-20 minutes until sauce thickens."}, {"title": "Step 8", "description": "Season with fish sauce and salt. Serve with puto or steamed rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Paksiw na Isda', 'Braised', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '800 kcal', 4292932350, '[{"name": "bangus or tilapia, sliced", "description": "150g bangus or tilapia, sliced", "amount": "150g", "market_section": "Fish Section", "product_key": "FISH_BANGUS_TILAPIA"}, {"name": "white vinegar", "description": "2 tbsp white vinegar", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WHITE_VINEGAR"}, {"name": "water", "description": "1/4 cup water", "amount": "1/4 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WATER"}, {"name": "1-inch ginger, sliced", "description": "1-inch ginger, sliced", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_INCH_GINGER"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "whole peppercorns", "description": "1/4 tsp whole peppercorns", "amount": "1/4 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WHOLE_PEPPERCORNS"}, {"name": "siling haba", "description": "1/2 pc siling haba", "amount": "1/2 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_HABA"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Salt or fish sauce to taste", "description": "Salt or fish sauce to taste", "amount": "1 serving", "market_section": "Fish Section", "product_key": "FISH_SALT_FISH_SAUCE"}]'::jsonb, '[{"title": "Step 1", "description": "Arrange ginger, garlic, and onion at the bottom of a pot."}, {"title": "Step 2", "description": "Layer fish on top."}, {"title": "Step 3", "description": "Pour vinegar and water over fish. Add peppercorns and siling haba."}, {"title": "Step 4", "description": "Do not stir. Bring to a boil over medium heat."}, {"title": "Step 5", "description": "Once boiling, lower heat. Simmer 15 minutes until fish is cooked and liquid slightly reduces."}, {"title": "Step 6", "description": "Drizzle cooking oil over the top."}, {"title": "Step 7", "description": "Season with salt or fish sauce. Serve hot."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginisang Ampalaya', 'Sautéed', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '180 kcal', 4292932350, '[{"name": "medium ampalaya, sliced", "description": "1/2 medium ampalaya, sliced", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_AMPALAYA"}, {"name": "large egg, beaten", "description": "1 large egg, beaten", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_LARGE_EGG"}, {"name": "cloves garlic, minced", "description": "2 cloves garlic, minced", "amount": "2", "market_section": "Vegetable Section", "product_key": "VEG_CLOVES_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "medium tomato", "description": "1/2 medium tomato", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_TOMATO"}, {"name": "bagoong alamang", "description": "1 tsp bagoong alamang", "amount": "1 tsp", "market_section": "Fish Section", "product_key": "FISH_BAGOONG_ALAMANG"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Rub sliced ampalaya with 1 tbsp salt. Let sit 15 minutes. Squeeze firmly to remove bitter liquid. Rinse and drain."}, {"title": "Step 2", "description": "Heat oil in pan over medium heat. Sauté garlic until golden."}, {"title": "Step 3", "description": "Add onion and tomatoes; cook until soft."}, {"title": "Step 4", "description": "Add bagoong; stir and cook 1 minute."}, {"title": "Step 5", "description": "Add ampalaya. Stir-fry 3-5 minutes until tender-crisp."}, {"title": "Step 6", "description": "Pour beaten eggs over ampalaya; let set briefly then scramble gently."}, {"title": "Step 7", "description": "Season with salt and pepper. Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Bulalo', 'Soup/Stew', '40 min', 'Hard', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '650 kcal', 4292932350, '[{"name": "beef shank with bone marrow", "description": "200g beef shank with bone marrow", "amount": "200g", "market_section": "Meat Section", "product_key": "MEAT_BEEF_SHANK_WITH"}, {"name": "corn", "description": "1/2 pc corn", "amount": "1/2 pc", "market_section": "Dry Goods / Condiments", "product_key": "DRY_CORN"}, {"name": "small cabbage", "description": "1/8 small cabbage", "amount": "1/8", "market_section": "Vegetable Section", "product_key": "VEG_SMALL_CABBAGE"}, {"name": "pechay", "description": "1/4 bundle pechay", "amount": "1/4 bundle", "market_section": "Vegetable Section", "product_key": "VEG_PECHAY"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "whole peppercorns", "description": "1/4 tsp whole peppercorns", "amount": "1/4 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WHOLE_PEPPERCORNS"}, {"name": "fish sauce", "description": "1 tbsp fish sauce", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE"}, {"name": "liter water", "description": "1 liter water", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_LITER_WATER"}]'::jsonb, '[{"title": "Step 1", "description": "Blanch beef shank in boiling water for 5 minutes. Discard water; rinse."}, {"title": "Step 2", "description": "Return beef to pot. Cover with fresh 3 liters water. Add onion and peppercorns."}, {"title": "Step 3", "description": "Bring to a boil; skim scum thoroughly."}, {"title": "Step 4", "description": "Simmer on low heat for 2.5-3 hours until beef is very tender and marrow is soft."}, {"title": "Step 5", "description": "Add corn. Cook 20 minutes."}, {"title": "Step 6", "description": "Add cabbage and pechay. Cook 5 minutes until tender."}, {"title": "Step 7", "description": "Season generously with fish sauce."}, {"title": "Step 8", "description": "Serve piping hot with corn, marrow, and all the vegetables."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Laing', 'Braised', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '3900 kcal', 4292932350, '[{"name": "dried taro leaves", "description": "50g dried taro leaves", "amount": "50g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_DRIED_TARO_LEAVES"}, {"name": "pork belly", "description": "100g pork belly", "amount": "100g", "market_section": "Meat Section", "product_key": "MEAT_PORK_BELLY"}, {"name": "thin coconut milk", "description": "150ml thin coconut milk", "amount": "150ml", "market_section": "Coconut Section", "product_key": "COCO_THIN_COCONUT_MILK"}, {"name": "coconut cream", "description": "75ml coconut cream", "amount": "75ml", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_CREAM"}, {"name": "bagoong alamang", "description": "1 tbsp bagoong alamang", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_BAGOONG_ALAMANG"}, {"name": "siling haba", "description": "1 pc siling haba", "amount": "1 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_HABA"}, {"name": "siling labuyo", "description": "1 pc siling labuyo", "amount": "1 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_LABUYO"}, {"name": "cloves garlic", "description": "2 cloves garlic", "amount": "2", "market_section": "Vegetable Section", "product_key": "VEG_CLOVES_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "1/2-inch ginger", "description": "1/2-inch ginger", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_INCH_GINGER"}]'::jsonb, '[{"title": "Step 1", "description": "Layer dried taro leaves at the bottom of a wide pot. Do NOT wash them."}, {"title": "Step 2", "description": "Scatter garlic, onion, and ginger over the leaves."}, {"title": "Step 3", "description": "Place pork on top. Add bagoong and all chilis."}, {"title": "Step 4", "description": "Pour thin coconut milk over everything. Do NOT stir."}, {"title": "Step 5", "description": "Bring to a boil over medium heat. Do not stir."}, {"title": "Step 6", "description": "Lower heat; simmer uncovered 20-25 minutes until coconut milk is mostly absorbed."}, {"title": "Step 7", "description": "Gently pour thick coconut cream over the top. Stir once or twice only."}, {"title": "Step 8", "description": "Simmer 10-15 more minutes until cream reduces and oil separates."}, {"title": "Step 9", "description": "Taste and adjust with more bagoong if needed. Serve with rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Bicol Express', 'Braised', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '4250 kcal', 4292932350, '[{"name": "pork belly", "description": "150g pork belly", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_PORK_BELLY"}, {"name": "coconut milk", "description": "150ml coconut milk", "amount": "150ml", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_MILK"}, {"name": "coconut cream", "description": "75ml coconut cream", "amount": "75ml", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_CREAM"}, {"name": "siling haba", "description": "1 pc siling haba", "amount": "1 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_HABA"}, {"name": "siling labuyo", "description": "1 pc siling labuyo", "amount": "1 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_LABUYO"}, {"name": "bagoong alamang", "description": "1 tbsp bagoong alamang", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_BAGOONG_ALAMANG"}, {"name": "cloves garlic", "description": "2 cloves garlic", "amount": "2", "market_section": "Vegetable Section", "product_key": "VEG_CLOVES_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil; sauté garlic and onion until soft."}, {"title": "Step 2", "description": "Add pork belly. Cook until lightly browned."}, {"title": "Step 3", "description": "Add bagoong; stir and cook 2 minutes."}, {"title": "Step 4", "description": "Add all chilis. Stir."}, {"title": "Step 5", "description": "Pour coconut milk. Bring to a boil."}, {"title": "Step 6", "description": "Simmer 15-20 minutes, stirring occasionally."}, {"title": "Step 7", "description": "Add coconut cream. Reduce until sauce is thick and oil separates."}, {"title": "Step 8", "description": "Serve with lots of steamed rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginataang Kalabasa', 'Sautéed', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1750 kcal', 4292932350, '[{"name": "kalabasa", "description": "150g kalabasa", "amount": "150g", "market_section": "Vegetable Section", "product_key": "VEG_KALABASA"}, {"name": "sitaw", "description": "75g sitaw", "amount": "75g", "market_section": "Vegetable Section", "product_key": "VEG_SITAW"}, {"name": "pork belly", "description": "75g pork belly", "amount": "75g", "market_section": "Meat Section", "product_key": "MEAT_PORK_BELLY"}, {"name": "shrimp", "description": "75g shrimp", "amount": "75g", "market_section": "Fish Section", "product_key": "FISH_SHRIMP"}, {"name": "coconut milk", "description": "150ml coconut milk", "amount": "150ml", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_MILK"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "bagoong alamang", "description": "1 tsp bagoong alamang", "amount": "1 tsp", "market_section": "Fish Section", "product_key": "FISH_BAGOONG_ALAMANG"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil; sauté garlic and onion."}, {"title": "Step 2", "description": "Add pork; cook until browned."}, {"title": "Step 3", "description": "Add shrimp; cook until pink."}, {"title": "Step 4", "description": "Add bagoong; stir 1 minute."}, {"title": "Step 5", "description": "Add kalabasa. Pour coconut milk over."}, {"title": "Step 6", "description": "Simmer 10 minutes until kalabasa starts to soften."}, {"title": "Step 7", "description": "Add sitaw. Cook 5 minutes more."}, {"title": "Step 8", "description": "Season with salt and pepper. Serve hot."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pritong Bangus', 'Grilled/Fried', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '500 kcal', 4292932350, '[{"name": "whole bangus, cleaned and butterflied", "description": "1/4 whole bangus, cleaned and butterflied", "amount": "1/4", "market_section": "Fish Section", "product_key": "FISH_WHOLE_BANGUS"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "calamansi juice", "description": "1 tbsp calamansi juice", "amount": "1 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_CALAMANSI_JUICE"}, {"name": "salt", "description": "1/4 tsp salt", "amount": "1/4 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT"}, {"name": "black pepper", "description": "1/8 tsp black pepper", "amount": "1/8 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BLACK_PEPPER"}, {"name": "cooking oil", "description": "1 tbsp cooking oil", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Score the flesh of the bangus with diagonal cuts 1 inch apart."}, {"title": "Step 2", "description": "Rub all over with garlic, calamansi juice, salt, and pepper. Marinate 15-30 minutes."}, {"title": "Step 3", "description": "Heat generous amount of oil in a large pan over medium-high heat."}, {"title": "Step 4", "description": "Fry bangus skin-side up first for 5-7 minutes until golden."}, {"title": "Step 5", "description": "Carefully flip; fry skin side 5-7 minutes until very crispy."}, {"title": "Step 6", "description": "Drain on wire rack. Serve immediately with tomato-onion salsa or spiced vinegar."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Escabeche', 'Sautéed', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '620 kcal', 4292932350, '[{"name": "fish, cleaned", "description": "150g fish, cleaned", "amount": "150g", "market_section": "Fish Section", "product_key": "FISH_FISH"}, {"name": "vinegar", "description": "1 tbsp vinegar", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_VINEGAR"}, {"name": "sugar", "description": "1 tsp sugar", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SUGAR"}, {"name": "medium carrot", "description": "1/4 medium carrot", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_CARROT"}, {"name": "red bell pepper", "description": "1/4 red bell pepper", "amount": "1/4", "market_section": "Dry Goods / Condiments", "product_key": "DRY_RED_BELL_PEPPER"}, {"name": "green bell pepper", "description": "1/4 green bell pepper", "amount": "1/4", "market_section": "Dry Goods / Condiments", "product_key": "DRY_GREEN_BELL_PEPPER"}, {"name": "1-inch ginger", "description": "1-inch ginger", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_INCH_GINGER"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "soy sauce", "description": "1 tsp soy sauce", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "water", "description": "2 tbsp water", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WATER"}, {"name": "cornstarch dissolved in 1 tbsp water", "description": "1 tsp cornstarch dissolved in 1 tbsp water", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_CORNSTARCH_DISSOLVED_TBSP"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "oil for frying", "description": "2 tbsp oil for frying", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_OIL_FOR_FRYING"}]'::jsonb, '[{"title": "Step 1", "description": "Season fish with salt and pepper. Fry in hot oil until golden crispy. Drain; set on serving plate."}, {"title": "Step 2", "description": "In same pan with 2 tbsp oil, sauté ginger and onion."}, {"title": "Step 3", "description": "Add carrots and bell peppers; stir-fry 2 minutes."}, {"title": "Step 4", "description": "Add vinegar, soy sauce, sugar, and water. Bring to a simmer."}, {"title": "Step 5", "description": "Add cornstarch mixture; stir until sauce thickens."}, {"title": "Step 6", "description": "Taste — should be sweet, sour, and savory."}, {"title": "Step 7", "description": "Pour sauce over fried fish. Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tokwa''t Baboy', 'Salad/Fresh', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1050 kcal', 4292932350, '[{"name": "pork ears, cleaned", "description": "150g pork ears, cleaned", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_PORK_EARS"}, {"name": "firm tokwa", "description": "100g firm tokwa", "amount": "100g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_FIRM_TOKWA"}, {"name": "vinegar", "description": "1 tbsp vinegar", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_VINEGAR"}, {"name": "soy sauce", "description": "1 tsp soy sauce", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "calamansi juice", "description": "1 tsp calamansi juice", "amount": "1 tsp", "market_section": "Vegetable Section", "product_key": "VEG_CALAMANSI_JUICE"}, {"name": "sugar", "description": "1/2 tsp sugar", "amount": "1/2 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SUGAR"}, {"name": "red onion", "description": "2 tbsp red onion", "amount": "2 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_RED_ONION"}, {"name": "siling labuyo", "description": "1/2 pc siling labuyo", "amount": "1/2 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_LABUYO"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "oil for frying", "description": "1 tbsp oil for frying", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_OIL_FOR_FRYING"}]'::jsonb, '[{"title": "Step 1", "description": "Boil pork ears in water with garlic and peppercorns for 1 hour until very tender. Cool; slice thinly."}, {"title": "Step 2", "description": "Drain tokwa; press to remove excess moisture. Cube into 1-inch pieces."}, {"title": "Step 3", "description": "Fry tokwa in hot oil until golden and crispy on all sides. Drain."}, {"title": "Step 4", "description": "Make dressing: combine vinegar, soy sauce, calamansi juice, sugar, onion, chili, and garlic. Mix well."}, {"title": "Step 5", "description": "Combine pork ears and tokwa on a plate."}, {"title": "Step 6", "description": "Pour dressing over. Toss gently. Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Caldereta', 'Braised', '40 min', 'Hard', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '700 kcal', 4292932350, '[{"name": "goat or beef", "description": "150g goat or beef", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_GOAT_BEEF"}, {"name": "tomato sauce", "description": "100g tomato sauce", "amount": "100g", "market_section": "Vegetable Section", "product_key": "VEG_TOMATO_SAUCE"}, {"name": "liver spread", "description": "40g liver spread", "amount": "40g", "market_section": "Meat Section", "product_key": "MEAT_LIVER_SPREAD"}, {"name": "medium potato", "description": "1/2 medium potato", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_POTATO"}, {"name": "medium carrot", "description": "1/2 medium carrot", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_CARROT"}, {"name": "red bell pepper", "description": "1/4 red bell pepper", "amount": "1/4", "market_section": "Dry Goods / Condiments", "product_key": "DRY_RED_BELL_PEPPER"}, {"name": "green olives", "description": "2 tbsp green olives", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_GREEN_OLIVES"}, {"name": "siling labuyo", "description": "1 pc siling labuyo", "amount": "1 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_LABUYO"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "water or broth", "description": "1/4 cup water or broth", "amount": "1/4 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WATER_BROTH"}, {"name": "oil", "description": "1 tsp oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_OIL"}, {"name": "Salt, pepper, and fish sauce to taste", "description": "Salt, pepper, and fish sauce to taste", "amount": "1 serving", "market_section": "Fish Section", "product_key": "FISH_SALT"}]'::jsonb, '[{"title": "Step 1", "description": "Marinate meat in vinegar, garlic, and pepper for 1 hour if using goat."}, {"title": "Step 2", "description": "Brown meat in hot oil. Remove; set aside."}, {"title": "Step 3", "description": "Sauté garlic and onion. Add tomato sauce; cook 3 minutes."}, {"title": "Step 4", "description": "Add liver spread; stir until incorporated."}, {"title": "Step 5", "description": "Return meat. Add water. Simmer covered 1-1.5 hours until tender."}, {"title": "Step 6", "description": "Add potatoes and carrots. Cook 15 minutes."}, {"title": "Step 7", "description": "Add bell peppers, olives, and chilis."}, {"title": "Step 8", "description": "Season with salt, pepper, fish sauce."}, {"title": "Step 9", "description": "Simmer 5 more minutes. Serve with rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Afritada', 'Braised', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '650 kcal', 4292932350, '[{"name": "chicken pieces", "description": "150g chicken pieces", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_CHICKEN_PIECES"}, {"name": "tomato sauce", "description": "100g tomato sauce", "amount": "100g", "market_section": "Vegetable Section", "product_key": "VEG_TOMATO_SAUCE"}, {"name": "medium potato", "description": "1/2 medium potato", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_POTATO"}, {"name": "medium carrot", "description": "1/2 medium carrot", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_CARROT"}, {"name": "red bell pepper", "description": "1/4 red bell pepper", "amount": "1/4", "market_section": "Dry Goods / Condiments", "product_key": "DRY_RED_BELL_PEPPER"}, {"name": "water", "description": "1/4 cup water", "amount": "1/4 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WATER"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "soy sauce", "description": "1 tsp soy sauce", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}]'::jsonb, '[{"title": "Step 1", "description": "Brown chicken in hot oil. Remove and set aside."}, {"title": "Step 2", "description": "Sauté garlic and onion in same pan."}, {"title": "Step 3", "description": "Add tomato sauce; cook 3 minutes."}, {"title": "Step 4", "description": "Add soy sauce and water. Return chicken."}, {"title": "Step 5", "description": "Simmer covered 20 minutes."}, {"title": "Step 6", "description": "Add potatoes and carrots. Cook 15 minutes."}, {"title": "Step 7", "description": "Add bell pepper. Cook 5 more minutes."}, {"title": "Step 8", "description": "Season with salt and pepper. Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pork Menudo', 'Sautéed', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1150 kcal', 4292932350, '[{"name": "pork shoulder", "description": "150g pork shoulder", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_PORK_SHOULDER"}, {"name": "pork liver", "description": "75g pork liver", "amount": "75g", "market_section": "Meat Section", "product_key": "MEAT_PORK_LIVER"}, {"name": "medium potato", "description": "1/2 medium potato", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_POTATO"}, {"name": "medium carrot", "description": "1/2 medium carrot", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_CARROT"}, {"name": "tomato sauce", "description": "100g tomato sauce", "amount": "100g", "market_section": "Vegetable Section", "product_key": "VEG_TOMATO_SAUCE"}, {"name": "raisins", "description": "1 tbsp raisins", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_RAISINS"}, {"name": "red bell pepper", "description": "1/4 red bell pepper", "amount": "1/4", "market_section": "Dry Goods / Condiments", "product_key": "DRY_RED_BELL_PEPPER"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "soy sauce", "description": "1 tsp soy sauce", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "water", "description": "2 tbsp water", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WATER"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil; sauté garlic and onion."}, {"title": "Step 2", "description": "Add pork; cook until browned."}, {"title": "Step 3", "description": "Add soy sauce and cook 2 minutes."}, {"title": "Step 4", "description": "Add tomato sauce and water. Simmer 15 minutes."}, {"title": "Step 5", "description": "Add potatoes and carrots. Cook 12 minutes."}, {"title": "Step 6", "description": "Add liver; cook 3 minutes (don''t overcook)."}, {"title": "Step 7", "description": "Add bell pepper and raisins."}, {"title": "Step 8", "description": "Season and simmer 3 more minutes. Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Chopsuey', 'Sautéed', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '650 kcal', 4292932350, '[{"name": "pork or chicken", "description": "100g pork or chicken", "amount": "100g", "market_section": "Meat Section", "product_key": "MEAT_PORK_CHICKEN"}, {"name": "shrimp", "description": "50g shrimp", "amount": "50g", "market_section": "Fish Section", "product_key": "FISH_SHRIMP"}, {"name": "cabbage", "description": "1/8 head cabbage", "amount": "1/8 head", "market_section": "Vegetable Section", "product_key": "VEG_CABBAGE"}, {"name": "medium carrot", "description": "1/2 medium carrot", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_CARROT"}, {"name": "snap peas or Baguio beans", "description": "50g snap peas or Baguio beans", "amount": "50g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SNAP_PEAS_BAGUIO"}, {"name": "cauliflower", "description": "50g cauliflower", "amount": "50g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_CAULIFLOWER"}, {"name": "quail eggs, optional", "description": "2 pcs quail eggs, optional", "amount": "2 pcs", "market_section": "Dry Goods / Condiments", "product_key": "DRY_QUAIL_EGGS"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "oyster sauce", "description": "1 tbsp oyster sauce", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_OYSTER_SAUCE"}, {"name": "soy sauce", "description": "1 tsp soy sauce", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "broth", "description": "2 tbsp broth", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BROTH"}, {"name": "cornstarch dissolved in 1 tbsp water", "description": "1 tsp cornstarch dissolved in 1 tbsp water", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_CORNSTARCH_DISSOLVED_TBSP"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Blanch hard vegetables (carrots, cauliflower) in salted water for 2 minutes. Drain."}, {"title": "Step 2", "description": "Heat oil; sauté garlic and onion."}, {"title": "Step 3", "description": "Add pork; cook until done. Add shrimp."}, {"title": "Step 4", "description": "Add all vegetables from firmest to softest."}, {"title": "Step 5", "description": "Add oyster sauce, soy sauce, and broth."}, {"title": "Step 6", "description": "Stir-fry on high heat 3-4 minutes."}, {"title": "Step 7", "description": "Add quail eggs if using."}, {"title": "Step 8", "description": "Pour cornstarch mixture to thicken sauce."}, {"title": "Step 9", "description": "Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pork Igado', 'Braised', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1100 kcal', 4292932350, '[{"name": "pork shoulder", "description": "150g pork shoulder", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_PORK_SHOULDER"}, {"name": "pork liver", "description": "75g pork liver", "amount": "75g", "market_section": "Meat Section", "product_key": "MEAT_PORK_LIVER"}, {"name": "red bell pepper", "description": "1/4 red bell pepper", "amount": "1/4", "market_section": "Dry Goods / Condiments", "product_key": "DRY_RED_BELL_PEPPER"}, {"name": "green peas", "description": "2 tbsp green peas", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_GREEN_PEAS"}, {"name": "vinegar", "description": "1 1/2 tbsp vinegar", "amount": "1 1/2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_VINEGAR"}, {"name": "soy sauce", "description": "1 tbsp soy sauce", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "peppercorns", "description": "1/4 tsp peppercorns", "amount": "1/4 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_PEPPERCORNS"}, {"name": "bay leaf", "description": "1 pc bay leaf", "amount": "1 pc", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BAY_LEAF"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Sauté garlic and onion in oil."}, {"title": "Step 2", "description": "Add pork; cook until browned."}, {"title": "Step 3", "description": "Add pork liver; cook 2 minutes."}, {"title": "Step 4", "description": "Pour vinegar; do not stir for 2 minutes."}, {"title": "Step 5", "description": "Add soy sauce, peppercorns, and bay leaves."}, {"title": "Step 6", "description": "Simmer 15-20 minutes until pork is tender and sauce reduces."}, {"title": "Step 7", "description": "Add bell pepper and green peas."}, {"title": "Step 8", "description": "Cook 3 more minutes. Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Inihaw na Liempo', 'Grilled/Fried', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1350 kcal', 4292932350, '[{"name": "pork belly", "description": "180g pork belly", "amount": "180g", "market_section": "Meat Section", "product_key": "MEAT_PORK_BELLY"}, {"name": "soy sauce", "description": "1 tbsp soy sauce", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "banana ketchup", "description": "1 tbsp banana ketchup", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BANANA_KETCHUP"}, {"name": "calamansi juice", "description": "1 tbsp calamansi juice", "amount": "1 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_CALAMANSI_JUICE"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "sugar", "description": "1 tsp sugar", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SUGAR"}, {"name": "black pepper", "description": "1/4 tsp black pepper", "amount": "1/4 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BLACK_PEPPER"}, {"name": "7-Up or Sprite", "description": "1 tbsp 7-Up or Sprite", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SPRITE"}]'::jsonb, '[{"title": "Step 1", "description": "Score pork belly skin every 2 inches."}, {"title": "Step 2", "description": "Combine all marinade ingredients. Marinate pork at least 4 hours or overnight."}, {"title": "Step 3", "description": "Prepare charcoal grill. Grill pork belly over medium heat."}, {"title": "Step 4", "description": "Baste with marinade every 3-4 minutes."}, {"title": "Step 5", "description": "Grill 20-25 minutes, flipping halfway, until cooked through with char marks."}, {"title": "Step 6", "description": "Rest 5 minutes before slicing."}, {"title": "Step 7", "description": "Serve with spiced vinegar and atchara (pickled papaya)."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Inihaw na Bangus', 'Grilled/Fried', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '650 kcal', 4292932350, '[{"name": "whole large bangus, cleaned", "description": "1/4 whole large bangus, cleaned", "amount": "1/4", "market_section": "Fish Section", "product_key": "FISH_WHOLE_LARGE_BANGUS"}, {"name": "medium tomato", "description": "1/2 medium tomato", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_TOMATO"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "1-inch ginger", "description": "1-inch ginger", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_INCH_GINGER"}, {"name": "soy sauce", "description": "1 tbsp soy sauce", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "calamansi juice", "description": "1 tbsp calamansi juice", "amount": "1 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_CALAMANSI_JUICE"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "small banana leaf", "description": "1 small banana leaf", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SMALL_BANANA_LEAF"}]'::jsonb, '[{"title": "Step 1", "description": "Score bangus inside flesh."}, {"title": "Step 2", "description": "Marinate with soy sauce, calamansi, salt, and pepper for 20 minutes."}, {"title": "Step 3", "description": "Mix tomatoes, onion, and ginger. Stuff inside fish cavity."}, {"title": "Step 4", "description": "Wilt banana leaf over flame. Wrap fish tightly."}, {"title": "Step 5", "description": "Grill over medium charcoal heat, 15-20 minutes per side."}, {"title": "Step 6", "description": "Unwrap carefully; serve with rice and soy-vinegar dip."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Nilaga', 'Soup/Stew', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '650 kcal', 4292932350, '[{"name": "beef shank or pork ribs", "description": "150g beef shank or pork ribs", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_BEEF_SHANK_PORK"}, {"name": "medium potato", "description": "1 medium potato", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_POTATO"}, {"name": "cabbage", "description": "1/8 head cabbage", "amount": "1/8 head", "market_section": "Vegetable Section", "product_key": "VEG_CABBAGE"}, {"name": "pechay", "description": "1/4 bundle pechay", "amount": "1/4 bundle", "market_section": "Vegetable Section", "product_key": "VEG_PECHAY"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "peppercorns", "description": "1/4 tsp peppercorns", "amount": "1/4 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_PEPPERCORNS"}, {"name": "fish sauce", "description": "1 tbsp fish sauce", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE"}, {"name": "liter water", "description": "1 liter water", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_LITER_WATER"}]'::jsonb, '[{"title": "Step 1", "description": "Blanch meat in boiling water 5 minutes. Rinse."}, {"title": "Step 2", "description": "Return meat to pot with fresh water, onion, and peppercorns."}, {"title": "Step 3", "description": "Boil; then simmer 1-1.5 hours until very tender."}, {"title": "Step 4", "description": "Add potatoes; cook 15 minutes."}, {"title": "Step 5", "description": "Add cabbage; cook 5 minutes."}, {"title": "Step 6", "description": "Add pechay; cook 2 minutes."}, {"title": "Step 7", "description": "Season generously with fish sauce. Serve hot."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Binagoongang Baboy', 'Sautéed', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1350 kcal', 4292932350, '[{"name": "pork belly", "description": "150g pork belly", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_PORK_BELLY"}, {"name": "bagoong alamang", "description": "1 tbsp bagoong alamang", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_BAGOONG_ALAMANG"}, {"name": "medium tomato", "description": "1/2 medium tomato", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_TOMATO"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "siling labuyo", "description": "1/2 pc siling labuyo", "amount": "1/2 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_LABUYO"}, {"name": "vinegar", "description": "1 tsp vinegar", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_VINEGAR"}, {"name": "sugar", "description": "1/2 tsp sugar", "amount": "1/2 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SUGAR"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Boil pork belly until tender. Slice into cubes."}, {"title": "Step 2", "description": "Pan-fry pork cubes until crispy. Drain and set aside."}, {"title": "Step 3", "description": "In same pan, sauté garlic, onion, and tomatoes."}, {"title": "Step 4", "description": "Add bagoong; cook 3 minutes stirring."}, {"title": "Step 5", "description": "Add chili, vinegar, and sugar. Balance flavors."}, {"title": "Step 6", "description": "Add crispy pork; toss to coat."}, {"title": "Step 7", "description": "Serve immediately over rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pork Humba', 'Braised', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '2250 kcal', 4292932350, '[{"name": "pork belly", "description": "180g pork belly", "amount": "180g", "market_section": "Meat Section", "product_key": "MEAT_PORK_BELLY"}, {"name": "tausi", "description": "1 tsp tausi", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_TAUSI"}, {"name": "palm or brown sugar", "description": "1 tsp palm or brown sugar", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_PALM_BROWN_SUGAR"}, {"name": "vinegar", "description": "1 tbsp vinegar", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_VINEGAR"}, {"name": "soy sauce", "description": "1 tbsp soy sauce", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "cloves garlic", "description": "2 cloves garlic", "amount": "2", "market_section": "Vegetable Section", "product_key": "VEG_CLOVES_GARLIC"}, {"name": "bay leaf", "description": "1 pc bay leaf", "amount": "1 pc", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BAY_LEAF"}, {"name": "dried banana blossom", "description": "2 tbsp dried banana blossom", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_DRIED_BANANA_BLOSSOM"}, {"name": "water", "description": "1/4 cup water", "amount": "1/4 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WATER"}]'::jsonb, '[{"title": "Step 1", "description": "Soak dried banana blossom in warm water 15 minutes. Drain."}, {"title": "Step 2", "description": "In a pot, combine all ingredients."}, {"title": "Step 3", "description": "Bring to a boil. Simmer covered on low heat 1-1.5 hours until pork is very tender."}, {"title": "Step 4", "description": "Uncover; increase heat slightly to reduce sauce until thick and dark."}, {"title": "Step 5", "description": "Stir to prevent burning as sauce thickens."}, {"title": "Step 6", "description": "Taste; adjust sugar and vinegar."}, {"title": "Step 7", "description": "Serve with steamed rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginisang Monggo', 'Soup/Stew', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '430 kcal', 4292932350, '[{"name": "mung beans, soaked", "description": "1/4 cup mung beans, soaked", "amount": "1/4 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_MUNG_BEANS"}, {"name": "pork", "description": "100g pork", "amount": "100g", "market_section": "Meat Section", "product_key": "MEAT_PORK"}, {"name": "tinapa flakes", "description": "2 tbsp tinapa flakes", "amount": "2 tbsp", "market_section": "Fish Section", "product_key": "FISH_TINAPA_FLAKES"}, {"name": "ampalaya leaves or kangkong", "description": "1/2 cup ampalaya leaves or kangkong", "amount": "1/2 cup", "market_section": "Vegetable Section", "product_key": "VEG_AMPALAYA_LEAVES_KANGKONG"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "medium tomato", "description": "1/2 medium tomato", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_TOMATO"}, {"name": "water", "description": "1 1/2 cups water", "amount": "1 1/2 cups", "market_section": "Dry Goods / Condiments", "product_key": "DRY_CUPS_WATER"}, {"name": "fish sauce", "description": "1 tbsp fish sauce", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Boil soaked monggo in water until tender and starting to break apart, about 30-40 minutes."}, {"title": "Step 2", "description": "In another pan, sauté garlic, onion, and tomatoes."}, {"title": "Step 3", "description": "Add pork; cook until done."}, {"title": "Step 4", "description": "Add tinapa flakes; stir."}, {"title": "Step 5", "description": "Combine with monggo; simmer together 10 minutes."}, {"title": "Step 6", "description": "Add greens; cook 2 minutes."}, {"title": "Step 7", "description": "Season with fish sauce. Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Lumpiang Shanghai', 'Grilled/Fried', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1550 kcal', 4292932350, '[{"name": "ground pork", "description": "150g ground pork", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_GROUND_PORK"}, {"name": "medium carrot", "description": "1/4 medium carrot", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_CARROT"}, {"name": "singkamas", "description": "2 tbsp singkamas", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SINGKAMAS"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "large egg, beaten", "description": "1/4 large egg, beaten", "amount": "1/4", "market_section": "Dry Goods / Condiments", "product_key": "DRY_LARGE_EGG"}, {"name": "soy sauce", "description": "1 tsp soy sauce", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "lumpia wrappers", "description": "6-8 lumpia wrappers", "amount": "6-8", "market_section": "Dry Goods / Condiments", "product_key": "DRY_LUMPIA_WRAPPERS"}, {"name": "Oil for frying", "description": "Oil for frying", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_OIL_FOR_FRYING"}, {"name": "sweet chili sauce", "description": "2 tbsp sweet chili sauce", "amount": "2 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_SWEET_CHILI_SAUCE"}]'::jsonb, '[{"title": "Step 1", "description": "Mix ground pork, carrot, singkamas, garlic, onion, egg, and soy sauce. Season."}, {"title": "Step 2", "description": "Lay one lumpia wrapper diagonally. Spoon 2 tbsp filling across the bottom third."}, {"title": "Step 3", "description": "Fold bottom over filling, then fold in sides. Roll tightly. Seal edge with egg or water."}, {"title": "Step 4", "description": "Repeat until filling is used."}, {"title": "Step 5", "description": "Heat oil to 170°C. Fry lumpia in batches until golden, about 5-7 minutes."}, {"title": "Step 6", "description": "Drain on rack. Serve hot with sweet chili sauce."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Chicken Inasal', 'Grilled/Fried', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '650 kcal', 4292932350, '[{"name": "chicken", "description": "150g chicken", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_CHICKEN"}, {"name": "calamansi juice", "description": "1 tbsp calamansi juice", "amount": "1 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_CALAMANSI_JUICE"}, {"name": "coconut vinegar", "description": "1 tbsp coconut vinegar", "amount": "1 tbsp", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_VINEGAR"}, {"name": "stalk lemongrass", "description": "1 stalk lemongrass", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_STALK_LEMONGRASS"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "1-inch ginger", "description": "1-inch ginger", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_INCH_GINGER"}, {"name": "annatto oil", "description": "1 tbsp annatto oil", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_ANNATTO_OIL"}, {"name": "salt", "description": "1/4 tsp salt", "amount": "1/4 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT"}, {"name": "sugar", "description": "1/4 tsp sugar", "amount": "1/4 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SUGAR"}]'::jsonb, '[{"title": "Step 1", "description": "Make annatto oil: heat seeds in oil until color releases. Strain; cool."}, {"title": "Step 2", "description": "Combine calamansi, vinegar, lemongrass, garlic, ginger, salt, and sugar."}, {"title": "Step 3", "description": "Marinate chicken at least 4 hours, ideally overnight."}, {"title": "Step 4", "description": "Thread on skewers for easier grilling."}, {"title": "Step 5", "description": "Grill over medium charcoal heat, basting with annatto oil every few minutes."}, {"title": "Step 6", "description": "Cook 20-25 minutes until juices run clear."}, {"title": "Step 7", "description": "Serve with garlic rice, spiced sinamak vinegar, and atchara."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tinolang Tahong', 'Soup/Stew', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '280 kcal', 4292932350, '[{"name": "fresh tahong", "description": "200g fresh tahong", "amount": "200g", "market_section": "Fish Section", "product_key": "FISH_FRESH_TAHONG"}, {"name": "1-inch ginger", "description": "1-inch ginger", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_INCH_GINGER"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "malunggay leaves", "description": "1/2 cup malunggay leaves", "amount": "1/2 cup", "market_section": "Vegetable Section", "product_key": "VEG_MALUNGGAY_LEAVES"}, {"name": "water", "description": "1/4 cup water", "amount": "1/4 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WATER"}, {"name": "fish sauce", "description": "1 tbsp fish sauce", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Sauté garlic and ginger in oil over medium heat until fragrant."}, {"title": "Step 2", "description": "Add onion; cook 2 minutes."}, {"title": "Step 3", "description": "Add mussels; stir to coat."}, {"title": "Step 4", "description": "Pour water over mussels. Cover with lid."}, {"title": "Step 5", "description": "Steam 5-7 minutes until mussels open."}, {"title": "Step 6", "description": "Discard any that don''t open."}, {"title": "Step 7", "description": "Add malunggay leaves. Season with fish sauce."}, {"title": "Step 8", "description": "Cook 1 more minute. Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginataang Hipon', 'Sautéed', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1200 kcal', 4292932350, '[{"name": "large shrimp", "description": "150g large shrimp", "amount": "150g", "market_section": "Fish Section", "product_key": "FISH_LARGE_SHRIMP"}, {"name": "coconut milk", "description": "150ml coconut milk", "amount": "150ml", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_MILK"}, {"name": "bagoong alamang", "description": "1 tsp bagoong alamang", "amount": "1 tsp", "market_section": "Fish Section", "product_key": "FISH_BAGOONG_ALAMANG"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "siling haba", "description": "1 pc siling haba", "amount": "1 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_HABA"}, {"name": "siling labuyo", "description": "1/2 pc siling labuyo", "amount": "1/2 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_LABUYO"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil; sauté garlic and onion."}, {"title": "Step 2", "description": "Add bagoong; stir 1 minute."}, {"title": "Step 3", "description": "Add shrimp; cook 2 minutes until pink."}, {"title": "Step 4", "description": "Add all chilis."}, {"title": "Step 5", "description": "Pour coconut milk. Bring to a simmer."}, {"title": "Step 6", "description": "Cook 8-10 minutes until sauce thickens slightly."}, {"title": "Step 7", "description": "Season with salt and pepper."}, {"title": "Step 8", "description": "Serve hot over rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Kilawin na Tanigue', 'Salad/Fresh', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '650 kcal', 4292932350, '[{"name": "fresh tanigue", "description": "150g fresh tanigue", "amount": "150g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_FRESH_TANIGUE"}, {"name": "calamansi juice", "description": "2 tbsp calamansi juice", "amount": "2 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_CALAMANSI_JUICE"}, {"name": "coconut vinegar", "description": "1 tbsp coconut vinegar", "amount": "1 tbsp", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_VINEGAR"}, {"name": "1-inch ginger", "description": "1-inch ginger", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_INCH_GINGER"}, {"name": "red onion", "description": "2 tbsp red onion", "amount": "2 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_RED_ONION"}, {"name": "siling labuyo", "description": "1/2 pc siling labuyo", "amount": "1/2 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_LABUYO"}, {"name": "coconut cream", "description": "1 tbsp coconut cream", "amount": "1 tbsp", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_CREAM"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}]'::jsonb, '[{"title": "Step 1", "description": "Use only the freshest sashimi-grade fish."}, {"title": "Step 2", "description": "Cube fish into 1-inch pieces."}, {"title": "Step 3", "description": "Combine calamansi and vinegar. Pour over fish."}, {"title": "Step 4", "description": "Toss; marinate 20-30 minutes until fish turns opaque (acid-cooked)."}, {"title": "Step 5", "description": "Drain some liquid."}, {"title": "Step 6", "description": "Add ginger, onion, and chili. Toss."}, {"title": "Step 7", "description": "Add coconut cream. Toss gently."}, {"title": "Step 8", "description": "Season with salt and pepper. Serve cold."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Adobong Pusit', 'Braised', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '650 kcal', 4292932350, '[{"name": "pusit", "description": "200g pusit", "amount": "200g", "market_section": "Fish Section", "product_key": "FISH_PUSIT"}, {"name": "vinegar", "description": "1 tbsp vinegar", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_VINEGAR"}, {"name": "soy sauce", "description": "1 tbsp soy sauce", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "medium tomato", "description": "1/2 medium tomato", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_TOMATO"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}]'::jsonb, '[{"title": "Step 1", "description": "Clean squid carefully, reserving ink sacs intact."}, {"title": "Step 2", "description": "Heat oil; sauté garlic, onion, and tomatoes."}, {"title": "Step 3", "description": "Add squid bodies and tentacles; cook 2 minutes."}, {"title": "Step 4", "description": "Add vinegar; let cook without stirring 2 minutes."}, {"title": "Step 5", "description": "Add soy sauce and ink sacs (pierce carefully over the pan)."}, {"title": "Step 6", "description": "Stir; simmer 10-12 minutes until sauce is thick and ink-black."}, {"title": "Step 7", "description": "Season; serve with rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pakbet Ilocano', 'Sautéed', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '700 kcal', 4292932350, '[{"name": "medium ampalaya", "description": "1/4 medium ampalaya", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_AMPALAYA"}, {"name": "medium eggplant", "description": "1/4 medium eggplant", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_EGGPLANT"}, {"name": "kalabasa", "description": "1/4 cup kalabasa", "amount": "1/4 cup", "market_section": "Vegetable Section", "product_key": "VEG_KALABASA"}, {"name": "okra", "description": "50g okra", "amount": "50g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_OKRA"}, {"name": "sitaw", "description": "50g sitaw", "amount": "50g", "market_section": "Vegetable Section", "product_key": "VEG_SITAW"}, {"name": "medium tomato", "description": "1/2 medium tomato", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_TOMATO"}, {"name": "pork", "description": "100g pork", "amount": "100g", "market_section": "Meat Section", "product_key": "MEAT_PORK"}, {"name": "bagoong isda", "description": "1 tbsp bagoong isda", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_BAGOONG_ISDA"}, {"name": "water", "description": "2 tbsp water", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WATER"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "In a pot, arrange pork at the bottom."}, {"title": "Step 2", "description": "Layer vegetables by cooking time: kalabasa, eggplant, sitaw, ampalaya, okra, tomatoes on top."}, {"title": "Step 3", "description": "Dissolve bagoong isda in water; pour over vegetables."}, {"title": "Step 4", "description": "Bring to a boil; do not stir."}, {"title": "Step 5", "description": "Lower heat; cover and simmer 15-20 minutes."}, {"title": "Step 6", "description": "Once vegetables are tender, gently fold once."}, {"title": "Step 7", "description": "Taste; adjust with more bagoong."}, {"title": "Step 8", "description": "Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pork Sisig', 'Grilled/Fried', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1350 kcal', 4292932350, '[{"name": "pork cheeks and ears", "description": "180g pork cheeks and ears", "amount": "180g", "market_section": "Meat Section", "product_key": "MEAT_PORK_CHEEKS_AND"}, {"name": "chicken liver", "description": "50g chicken liver", "amount": "50g", "market_section": "Meat Section", "product_key": "MEAT_CHICKEN_LIVER"}, {"name": "large onion", "description": "1/4 large onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_LARGE_ONION"}, {"name": "siling labuyo", "description": "1 pc siling labuyo", "amount": "1 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_LABUYO"}, {"name": "calamansi juice", "description": "1 tbsp calamansi juice", "amount": "1 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_CALAMANSI_JUICE"}, {"name": "soy sauce", "description": "1 tsp soy sauce", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "mayonnaise", "description": "1 tsp mayonnaise", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_MAYONNAISE"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "large egg, optional", "description": "1/2 large egg, optional", "amount": "1/2", "market_section": "Dry Goods / Condiments", "product_key": "DRY_LARGE_EGG"}]'::jsonb, '[{"title": "Step 1", "description": "Boil pork cheeks and ears until tender (about 45 minutes). Drain."}, {"title": "Step 2", "description": "Grill boiled pork and chicken liver until charred. Chop into small pieces."}, {"title": "Step 3", "description": "Heat sizzling plate (cast iron) until very hot."}, {"title": "Step 4", "description": "Add butter; toss in pork and liver."}, {"title": "Step 5", "description": "Add onion and chili; sear together."}, {"title": "Step 6", "description": "Season with soy sauce and calamansi."}, {"title": "Step 7", "description": "Add mayonnaise; toss."}, {"title": "Step 8", "description": "Crack egg on top (optional); mix before eating."}, {"title": "Step 9", "description": "Serve sizzling."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Goto', 'Noodles/Rice', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '650 kcal', 4292932350, '[{"name": "glutinous rice", "description": "1/4 cup glutinous rice", "amount": "1/4 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_GLUTINOUS_RICE"}, {"name": "beef tripe", "description": "150g beef tripe", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_BEEF_TRIPE"}, {"name": "1-inch ginger", "description": "1-inch ginger", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_INCH_GINGER"}, {"name": "cloves garlic", "description": "2 cloves garlic", "amount": "2", "market_section": "Vegetable Section", "product_key": "VEG_CLOVES_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "broth or water", "description": "2 cups broth or water", "amount": "2 cups", "market_section": "Dry Goods / Condiments", "product_key": "DRY_CUPS_BROTH_WATER"}, {"name": "fish sauce", "description": "1 tbsp fish sauce", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE"}, {"name": "hard-boiled egg and toppings, optional", "description": "1 hard-boiled egg and toppings, optional", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_HARD_BOILED_EGG"}]'::jsonb, '[{"title": "Step 1", "description": "Boil tripe with garlic, ginger, and onion until very tender (1-2 hours). Reserve broth. Slice tripe."}, {"title": "Step 2", "description": "In reserved broth, cook glutinous rice to a porridge consistency, 30-40 minutes."}, {"title": "Step 3", "description": "Add sliced tripe; simmer together 10 minutes."}, {"title": "Step 4", "description": "Season with fish sauce."}, {"title": "Step 5", "description": "Serve in bowls topped with egg, chicharron, fried garlic, scallions, and calamansi."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginataang Manok', 'Braised', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1500 kcal', 4292932350, '[{"name": "chicken", "description": "150g chicken", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_CHICKEN"}, {"name": "coconut milk", "description": "150ml coconut milk", "amount": "150ml", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_MILK"}, {"name": "coconut cream", "description": "75ml coconut cream", "amount": "75ml", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_CREAM"}, {"name": "1-inch ginger", "description": "1-inch ginger", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_INCH_GINGER"}, {"name": "cloves garlic", "description": "2 cloves garlic", "amount": "2", "market_section": "Vegetable Section", "product_key": "VEG_CLOVES_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "siling haba", "description": "1 pc siling haba", "amount": "1 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_HABA"}, {"name": "fish sauce", "description": "1 tbsp fish sauce", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Sauté ginger in oil until fragrant."}, {"title": "Step 2", "description": "Add garlic and onion; cook until soft."}, {"title": "Step 3", "description": "Add chicken; brown on all sides."}, {"title": "Step 4", "description": "Pour coconut milk. Bring to a boil."}, {"title": "Step 5", "description": "Add chilis. Simmer covered 20-25 minutes."}, {"title": "Step 6", "description": "Add coconut cream. Simmer uncovered 10 minutes until sauce thickens."}, {"title": "Step 7", "description": "Season with fish sauce. Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pininyahang Manok', 'Braised', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1100 kcal', 4292932350, '[{"name": "chicken", "description": "150g chicken", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_CHICKEN"}, {"name": "pineapple chunks with 2 tbsp juice", "description": "1/2 cup pineapple chunks with 2 tbsp juice", "amount": "1/2 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_PINEAPPLE_CHUNKS_WITH"}, {"name": "all-purpose cream", "description": "100ml all-purpose cream", "amount": "100ml", "market_section": "Dry Goods / Condiments", "product_key": "DRY_ALL_PURPOSE_CREAM"}, {"name": "medium potato", "description": "1/2 medium potato", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_POTATO"}, {"name": "medium carrot", "description": "1/2 medium carrot", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_CARROT"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "soy sauce", "description": "1 tsp soy sauce", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}]'::jsonb, '[{"title": "Step 1", "description": "Brown chicken in oil. Remove and set aside."}, {"title": "Step 2", "description": "Sauté garlic and onion."}, {"title": "Step 3", "description": "Return chicken. Add pineapple juice and soy sauce."}, {"title": "Step 4", "description": "Simmer 20 minutes."}, {"title": "Step 5", "description": "Add potatoes and carrots. Cook 12 minutes."}, {"title": "Step 6", "description": "Add pineapple chunks and cream."}, {"title": "Step 7", "description": "Simmer 5 more minutes."}, {"title": "Step 8", "description": "Season; serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Kinilaw na Tuna', 'Salad/Fresh', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '750 kcal', 4292932350, '[{"name": "sashimi-grade fresh tuna", "description": "150g sashimi-grade fresh tuna", "amount": "150g", "market_section": "Fish Section", "product_key": "FISH_SASHIMI_GRADE_FRESH"}, {"name": "coconut vinegar", "description": "1 1/2 tbsp coconut vinegar", "amount": "1 1/2 tbsp", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_VINEGAR"}, {"name": "calamansi juice", "description": "1 tbsp calamansi juice", "amount": "1 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_CALAMANSI_JUICE"}, {"name": "1-inch ginger", "description": "1-inch ginger", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_INCH_GINGER"}, {"name": "red onion", "description": "2 tbsp red onion", "amount": "2 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_RED_ONION"}, {"name": "siling labuyo", "description": "1/2 pc siling labuyo", "amount": "1/2 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_LABUYO"}, {"name": "coconut cream", "description": "1 tbsp coconut cream", "amount": "1 tbsp", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_CREAM"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}]'::jsonb, '[{"title": "Step 1", "description": "Cube tuna into 1-inch pieces."}, {"title": "Step 2", "description": "Toss with vinegar and calamansi. Let sit 15-20 minutes until opaque."}, {"title": "Step 3", "description": "Drain most liquid."}, {"title": "Step 4", "description": "Add ginger, onion, and chili. Mix."}, {"title": "Step 5", "description": "Add coconut cream. Toss gently."}, {"title": "Step 6", "description": "Season with salt and pepper."}, {"title": "Step 7", "description": "Serve cold immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pancit Batchoy', 'Noodles/Rice', '40 min', 'Hard', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '2100 kcal', 4292932350, '[{"name": "fresh miki noodles", "description": "100g fresh miki noodles", "amount": "100g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_FRESH_MIKI_NOODLES"}, {"name": "pork", "description": "75g pork", "amount": "75g", "market_section": "Meat Section", "product_key": "MEAT_PORK"}, {"name": "pork liver", "description": "40g pork liver", "amount": "40g", "market_section": "Meat Section", "product_key": "MEAT_PORK_LIVER"}, {"name": "pork intestine", "description": "40g pork intestine", "amount": "40g", "market_section": "Meat Section", "product_key": "MEAT_PORK_INTESTINE"}, {"name": "chicharon", "description": "20g chicharon", "amount": "20g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_CHICHARON"}, {"name": "pork bone broth", "description": "1 1/2 cups pork bone broth", "amount": "1 1/2 cups", "market_section": "Meat Section", "product_key": "MEAT_CUPS_PORK_BONE"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "shrimp paste", "description": "1 tsp shrimp paste", "amount": "1 tsp", "market_section": "Fish Section", "product_key": "FISH_SHRIMP_PASTE"}, {"name": "Fish sauce", "description": "Fish sauce", "amount": "1 serving", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE"}, {"name": "green onion", "description": "1 tbsp green onion", "amount": "1 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_GREEN_ONION"}]'::jsonb, '[{"title": "Step 1", "description": "Make broth: boil pork bones 2 hours with garlic, onion, shrimp paste. Strain."}, {"title": "Step 2", "description": "Cook intestines separately; slice."}, {"title": "Step 3", "description": "Blanch noodles in boiling water. Divide into bowls."}, {"title": "Step 4", "description": "In broth, quickly cook pork slices and liver (30 seconds)."}, {"title": "Step 5", "description": "Ladle hot broth with meat over noodles."}, {"title": "Step 6", "description": "Top with intestine, chicharron, fried garlic, green onion."}, {"title": "Step 7", "description": "Serve with fish sauce and calamansi."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Karekare sa Gabi', 'Soup/Stew', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '350 kcal', 4292932350, '[{"name": "gabi", "description": "1/2 cup gabi", "amount": "1/2 cup", "market_section": "Vegetable Section", "product_key": "VEG_GABI"}, {"name": "eggplant", "description": "1/4 cup eggplant", "amount": "1/4 cup", "market_section": "Vegetable Section", "product_key": "VEG_EGGPLANT"}, {"name": "sitaw", "description": "1/4 cup sitaw", "amount": "1/4 cup", "market_section": "Vegetable Section", "product_key": "VEG_SITAW"}, {"name": "pechay", "description": "1/4 cup pechay", "amount": "1/4 cup", "market_section": "Vegetable Section", "product_key": "VEG_PECHAY"}, {"name": "banana blossom", "description": "2 tbsp banana blossom", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BANANA_BLOSSOM"}, {"name": "peanut butter", "description": "1 tbsp peanut butter", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_PEANUT_BUTTER"}, {"name": "ground peanuts", "description": "1 tbsp ground peanuts", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_GROUND_PEANUTS"}, {"name": "annatto water", "description": "1 tsp annatto water", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_ANNATTO_WATER"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "broth", "description": "3/4 cup broth", "amount": "3/4 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BROTH"}, {"name": "bagoong", "description": "1 tbsp bagoong", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BAGOONG"}]'::jsonb, '[{"title": "Step 1", "description": "Sauté garlic and onion in oil."}, {"title": "Step 2", "description": "Add annatto water; cook 1 minute."}, {"title": "Step 3", "description": "Add peanut butter and ground peanuts; stir."}, {"title": "Step 4", "description": "Slowly add broth, stirring to prevent lumps."}, {"title": "Step 5", "description": "Add gabi; simmer until almost tender, 12 minutes."}, {"title": "Step 6", "description": "Add eggplant and banana blossom."}, {"title": "Step 7", "description": "Add sitaw and pechay last."}, {"title": "Step 8", "description": "Serve with bagoong on side."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pinapaitan', 'Soup/Stew', '40 min', 'Hard', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1150 kcal', 4292932350, '[{"name": "goat tripe and meat", "description": "150g goat tripe and meat", "amount": "150g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_GOAT_TRIPE_AND"}, {"name": "bile", "description": "1 tsp bile", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BILE"}, {"name": "1-inch ginger", "description": "1-inch ginger", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_INCH_GINGER"}, {"name": "siling labuyo", "description": "1 pc siling labuyo", "amount": "1 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_LABUYO"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "fish sauce", "description": "1 tbsp fish sauce", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE"}, {"name": "water", "description": "1 cup water", "amount": "1 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WATER"}]'::jsonb, '[{"title": "Step 1", "description": "Boil goat meat and tripe with ginger, garlic, and onion until tender, about 1 hour."}, {"title": "Step 2", "description": "Remove meat; slice thinly."}, {"title": "Step 3", "description": "Return to broth."}, {"title": "Step 4", "description": "Add bile gradually — 1 tbsp at a time. Taste after each addition."}, {"title": "Step 5", "description": "Add chilis. Simmer 10 minutes."}, {"title": "Step 6", "description": "Season with fish sauce."}, {"title": "Step 7", "description": "Serve hot."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Sinanglay na Isda', 'Braised', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '700 kcal', 4292932350, '[{"name": "tilapia", "description": "200g tilapia", "amount": "200g", "market_section": "Fish Section", "product_key": "FISH_TILAPIA"}, {"name": "medium tomato", "description": "1/2 medium tomato", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_TOMATO"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "1-inch ginger", "description": "1-inch ginger", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_INCH_GINGER"}, {"name": "coconut milk", "description": "150ml coconut milk", "amount": "150ml", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_MILK"}, {"name": "siling haba", "description": "1 pc siling haba", "amount": "1 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_HABA"}, {"name": "Pechay or leafy greens", "description": "Pechay or leafy greens", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_PECHAY_LEAFY_GREENS"}, {"name": "fish sauce", "description": "1 tbsp fish sauce", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}]'::jsonb, '[{"title": "Step 1", "description": "Season fish inside and out with salt and pepper."}, {"title": "Step 2", "description": "Mix tomatoes, onion, and ginger; stuff into fish cavity."}, {"title": "Step 3", "description": "Wrap each fish in pechay leaves, securing with pandan or string."}, {"title": "Step 4", "description": "Arrange in pot. Pour coconut milk over."}, {"title": "Step 5", "description": "Add chilis."}, {"title": "Step 6", "description": "Simmer covered 20-25 minutes until fish is cooked and coconut milk reduced."}, {"title": "Step 7", "description": "Season with fish sauce. Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Daing na Bangus', 'Grilled/Fried', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '550 kcal', 4292932350, '[{"name": "large bangus, butterflied and deboned", "description": "1/4 large bangus, butterflied and deboned", "amount": "1/4", "market_section": "Fish Section", "product_key": "FISH_LARGE_BANGUS"}, {"name": "white vinegar", "description": "2 tbsp white vinegar", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WHITE_VINEGAR"}, {"name": "cloves garlic", "description": "2 cloves garlic", "amount": "2", "market_section": "Vegetable Section", "product_key": "VEG_CLOVES_GARLIC"}, {"name": "peppercorns", "description": "1/4 tsp peppercorns", "amount": "1/4 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_PEPPERCORNS"}, {"name": "salt", "description": "1/4 tsp salt", "amount": "1/4 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT"}, {"name": "cooking oil", "description": "1 tbsp cooking oil", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Combine vinegar, garlic, peppercorns, and salt."}, {"title": "Step 2", "description": "Place bangus flesh-side down in marinade. Refrigerate overnight (minimum 8 hours)."}, {"title": "Step 3", "description": "Drain and pat dry."}, {"title": "Step 4", "description": "Heat generous oil in pan over medium-high heat."}, {"title": "Step 5", "description": "Fry flesh-side up first for 4-5 minutes, then skin-side until crispy."}, {"title": "Step 6", "description": "Drain. Serve with garlic rice and sunny-side-up eggs."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Longganisang Hubad', 'Grilled/Fried', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1320 kcal', 4292932350, '[{"name": "ground pork", "description": "150g ground pork", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_GROUND_PORK"}, {"name": "cloves garlic", "description": "2 cloves garlic", "amount": "2", "market_section": "Vegetable Section", "product_key": "VEG_CLOVES_GARLIC"}, {"name": "sugar", "description": "1 tsp sugar", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SUGAR"}, {"name": "vinegar", "description": "1 tsp vinegar", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_VINEGAR"}, {"name": "salt", "description": "1/4 tsp salt", "amount": "1/4 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT"}, {"name": "black pepper", "description": "1/8 tsp black pepper", "amount": "1/8 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BLACK_PEPPER"}, {"name": "soy sauce", "description": "1 tsp soy sauce", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}]'::jsonb, '[{"title": "Step 1", "description": "Combine all ingredients thoroughly. Refrigerate overnight."}, {"title": "Step 2", "description": "Shape into small oval logs."}, {"title": "Step 3", "description": "Cook in pan with a little oil over medium heat."}, {"title": "Step 4", "description": "As fat renders, increase heat slightly."}, {"title": "Step 5", "description": "Cook until caramelized and cooked through, about 8-10 minutes."}, {"title": "Step 6", "description": "Serve with garlic rice, egg, and vinegar dip."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Bagoong Guisado', 'Preserved', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '420 kcal', 4292932350, '[{"name": "bagoong alamang", "description": "2 tbsp bagoong alamang", "amount": "2 tbsp", "market_section": "Fish Section", "product_key": "FISH_BAGOONG_ALAMANG"}, {"name": "pork", "description": "75g pork", "amount": "75g", "market_section": "Meat Section", "product_key": "MEAT_PORK"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "medium tomato", "description": "1/2 medium tomato", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_TOMATO"}, {"name": "vinegar", "description": "1 tsp vinegar", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_VINEGAR"}, {"name": "sugar", "description": "1/2 tsp sugar", "amount": "1/2 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SUGAR"}, {"name": "siling labuyo, optional", "description": "1/2 pc siling labuyo, optional", "amount": "1/2 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_LABUYO"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil; sauté garlic, onion, and tomatoes until soft."}, {"title": "Step 2", "description": "Add pork; cook until browned."}, {"title": "Step 3", "description": "Add bagoong; stir and cook 5 minutes."}, {"title": "Step 4", "description": "Add vinegar; cook 2 minutes."}, {"title": "Step 5", "description": "Add sugar; balance flavors."}, {"title": "Step 6", "description": "Simmer on low 10 minutes until well-combined."}, {"title": "Step 7", "description": "Cool and store in jar. Keeps 2 weeks refrigerated."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginataang Tambo', 'Sautéed', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1900 kcal', 4292932350, '[{"name": "labong", "description": "150g labong", "amount": "150g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_LABONG"}, {"name": "coconut milk", "description": "150ml coconut milk", "amount": "150ml", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_MILK"}, {"name": "pork belly", "description": "75g pork belly", "amount": "75g", "market_section": "Meat Section", "product_key": "MEAT_PORK_BELLY"}, {"name": "shrimp", "description": "75g shrimp", "amount": "75g", "market_section": "Fish Section", "product_key": "FISH_SHRIMP"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "siling haba", "description": "1 pc siling haba", "amount": "1 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_HABA"}, {"name": "bagoong alamang", "description": "1 tsp bagoong alamang", "amount": "1 tsp", "market_section": "Fish Section", "product_key": "FISH_BAGOONG_ALAMANG"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Boil labong in several changes of water (3x) for 20 minutes total to remove bitterness and toxins."}, {"title": "Step 2", "description": "Drain; squeeze dry."}, {"title": "Step 3", "description": "Sauté garlic and onion. Add pork; brown."}, {"title": "Step 4", "description": "Add shrimp; cook 1 minute."}, {"title": "Step 5", "description": "Add labong; stir."}, {"title": "Step 6", "description": "Add bagoong and chilis."}, {"title": "Step 7", "description": "Pour coconut milk; simmer 15 minutes until thick."}, {"title": "Step 8", "description": "Season; serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pochero', 'Soup/Stew', '40 min', 'Hard', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1550 kcal', 4292932350, '[{"name": "beef shank", "description": "100g beef shank", "amount": "100g", "market_section": "Meat Section", "product_key": "MEAT_BEEF_SHANK"}, {"name": "pork belly", "description": "75g pork belly", "amount": "75g", "market_section": "Meat Section", "product_key": "MEAT_PORK_BELLY"}, {"name": "chorizo de Bilbao", "description": "1/2 pc chorizo de Bilbao", "amount": "1/2 pc", "market_section": "Dry Goods / Condiments", "product_key": "DRY_CHORIZO_BILBAO"}, {"name": "saba", "description": "1/2 pc saba", "amount": "1/2 pc", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SABA"}, {"name": "medium potato", "description": "1/2 medium potato", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_POTATO"}, {"name": "cabbage", "description": "1/8 head cabbage", "amount": "1/8 head", "market_section": "Vegetable Section", "product_key": "VEG_CABBAGE"}, {"name": "pechay", "description": "1/4 bundle pechay", "amount": "1/4 bundle", "market_section": "Vegetable Section", "product_key": "VEG_PECHAY"}, {"name": "chickpeas", "description": "1/4 cup chickpeas", "amount": "1/4 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_CHICKPEAS"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "tomato sauce", "description": "1/2 cup tomato sauce", "amount": "1/2 cup", "market_section": "Vegetable Section", "product_key": "VEG_TOMATO_SAUCE"}]'::jsonb, '[{"title": "Step 1", "description": "Boil beef and pork together 1 hour until tender."}, {"title": "Step 2", "description": "Add chorizo; cook 15 minutes."}, {"title": "Step 3", "description": "Add saba and chickpeas."}, {"title": "Step 4", "description": "Add potatoes; cook 15 minutes."}, {"title": "Step 5", "description": "Add cabbage and pechay."}, {"title": "Step 6", "description": "Serve each component in a bowl."}, {"title": "Step 7", "description": "Serve sautéed tomato sauce separately for dipping."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Morcon', 'Braised', '40 min', 'Hard', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '2150 kcal', 4292932350, '[{"name": "beef flank", "description": "180g beef flank", "amount": "180g", "market_section": "Meat Section", "product_key": "MEAT_BEEF_FLANK"}, {"name": "hard-boiled egg", "description": "1/2 hard-boiled egg", "amount": "1/2", "market_section": "Dry Goods / Condiments", "product_key": "DRY_HARD_BOILED_EGG"}, {"name": "medium carrot", "description": "1/4 medium carrot", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_CARROT"}, {"name": "sweet pickles", "description": "1 tbsp sweet pickles", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SWEET_PICKLES"}, {"name": "hotdog", "description": "1/2 pc hotdog", "amount": "1/2 pc", "market_section": "Dry Goods / Condiments", "product_key": "DRY_HOTDOG"}, {"name": "tomato sauce", "description": "1/2 cup tomato sauce", "amount": "1/2 cup", "market_section": "Vegetable Section", "product_key": "VEG_TOMATO_SAUCE"}, {"name": "soy sauce", "description": "1 tbsp soy sauce", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "water", "description": "1/4 cup water", "amount": "1/4 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WATER"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "toothpicks or kitchen string", "description": "toothpicks or kitchen string", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_TOOTHPICKS_KITCHEN_STRING"}]'::jsonb, '[{"title": "Step 1", "description": "Pound beef flat. Season with soy sauce, salt, and pepper."}, {"title": "Step 2", "description": "Arrange stuffing (eggs, carrots, pickles, hotdog) along one edge."}, {"title": "Step 3", "description": "Roll tightly; tie with string or secure with toothpicks."}, {"title": "Step 4", "description": "Brown roll on all sides in hot oil."}, {"title": "Step 5", "description": "Place in pot with tomato sauce, soy sauce, and water."}, {"title": "Step 6", "description": "Simmer covered 1.5-2 hours until tender."}, {"title": "Step 7", "description": "Remove string; slice into rounds."}, {"title": "Step 8", "description": "Reduce sauce; pour over slices."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Embutido', 'Braised', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1900 kcal', 4292932350, '[{"name": "ground pork", "description": "150g ground pork", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_GROUND_PORK"}, {"name": "hard-boiled egg", "description": "1 hard-boiled egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_HARD_BOILED_EGG"}, {"name": "raisins", "description": "1 tbsp raisins", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_RAISINS"}, {"name": "red bell pepper", "description": "1/4 red bell pepper", "amount": "1/4", "market_section": "Dry Goods / Condiments", "product_key": "DRY_RED_BELL_PEPPER"}, {"name": "sweet pickle relish", "description": "1 tsp sweet pickle relish", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SWEET_PICKLE_RELISH"}, {"name": "breadcrumbs", "description": "1 tbsp breadcrumbs", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BREADCRUMBS"}, {"name": "large egg, raw", "description": "1/4 large egg, raw", "amount": "1/4", "market_section": "Dry Goods / Condiments", "product_key": "DRY_LARGE_EGG"}, {"name": "soy sauce", "description": "1 tsp soy sauce", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "Aluminum foil", "description": "Aluminum foil", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_ALUMINUM_FOIL"}]'::jsonb, '[{"title": "Step 1", "description": "Combine ground pork, raw egg, breadcrumbs, bell pepper, relish, raisins, soy sauce. Season."}, {"title": "Step 2", "description": "Lay mixture on foil; flatten into a rectangle."}, {"title": "Step 3", "description": "Place whole boiled eggs along one edge."}, {"title": "Step 4", "description": "Roll into a log, encasing the eggs in the center."}, {"title": "Step 5", "description": "Seal foil tightly."}, {"title": "Step 6", "description": "Steam for 45-50 minutes."}, {"title": "Step 7", "description": "Cool before unwrapping. Slice to reveal egg center."}, {"title": "Step 8", "description": "Pan-fry slices optionally for a browned exterior."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginataang Kuhol', 'Braised', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1400 kcal', 4292932350, '[{"name": "kuhol", "description": "200g kuhol", "amount": "200g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_KUHOL"}, {"name": "coconut milk", "description": "150ml coconut milk", "amount": "150ml", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_MILK"}, {"name": "bagoong alamang", "description": "1 tsp bagoong alamang", "amount": "1 tsp", "market_section": "Fish Section", "product_key": "FISH_BAGOONG_ALAMANG"}, {"name": "1-inch ginger", "description": "1-inch ginger", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_INCH_GINGER"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "siling haba", "description": "1 pc siling haba", "amount": "1 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_HABA"}, {"name": "siling labuyo", "description": "1/2 pc siling labuyo", "amount": "1/2 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_LABUYO"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Clean snails: soak in salted water 30 minutes, scrub shells, trim off sealed operculum."}, {"title": "Step 2", "description": "Sauté ginger, garlic, and onion in oil."}, {"title": "Step 3", "description": "Add bagoong; cook 2 minutes."}, {"title": "Step 4", "description": "Add snails; stir to coat."}, {"title": "Step 5", "description": "Pour coconut milk. Add chilis."}, {"title": "Step 6", "description": "Simmer covered 20-25 minutes until snails are tender."}, {"title": "Step 7", "description": "Uncover; reduce sauce 5 minutes."}, {"title": "Step 8", "description": "Serve — suck meat from shells at the table."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Adobong Kangkong', 'Sautéed', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '250 kcal', 4292932350, '[{"name": "kangkong", "description": "1/2 bundle kangkong", "amount": "1/2 bundle", "market_section": "Vegetable Section", "product_key": "VEG_KANGKONG"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "vinegar", "description": "1 tbsp vinegar", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_VINEGAR"}, {"name": "soy sauce", "description": "1 tbsp soy sauce", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "pork or shrimp", "description": "100g pork or shrimp", "amount": "100g", "market_section": "Meat Section", "product_key": "MEAT_PORK_SHRIMP"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}]'::jsonb, '[{"title": "Step 1", "description": "Separate kangkong leaves from stems. Cut stems into 2-inch pieces."}, {"title": "Step 2", "description": "Heat oil; sauté garlic until golden."}, {"title": "Step 3", "description": "Add pork; cook until browned."}, {"title": "Step 4", "description": "Add kangkong stems; stir-fry 1 minute."}, {"title": "Step 5", "description": "Add kangkong leaves."}, {"title": "Step 6", "description": "Add vinegar and soy sauce. Cover; cook 2 minutes."}, {"title": "Step 7", "description": "Season and serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ukoy', 'Grilled/Fried', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '360 kcal', 4292932350, '[{"name": "small shrimp", "description": "100g small shrimp", "amount": "100g", "market_section": "Fish Section", "product_key": "FISH_SMALL_SHRIMP"}, {"name": "kalabasa", "description": "1/4 cup kalabasa", "amount": "1/4 cup", "market_section": "Vegetable Section", "product_key": "VEG_KALABASA"}, {"name": "bean sprouts", "description": "1/4 cup bean sprouts", "amount": "1/4 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BEAN_SPROUTS"}, {"name": "flour", "description": "2 tbsp flour", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_FLOUR"}, {"name": "cornstarch", "description": "1 tbsp cornstarch", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_CORNSTARCH"}, {"name": "large egg", "description": "1/2 large egg", "amount": "1/2", "market_section": "Dry Goods / Condiments", "product_key": "DRY_LARGE_EGG"}, {"name": "water", "description": "2 tbsp water", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WATER"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "Oil for deep-frying", "description": "Oil for deep-frying", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_OIL_FOR_DEEP"}, {"name": "spiced vinegar", "description": "2 tbsp spiced vinegar", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SPICED_VINEGAR"}]'::jsonb, '[{"title": "Step 1", "description": "Make batter: whisk flour, cornstarch, egg, water, salt, and pepper."}, {"title": "Step 2", "description": "Add shrimp, kalabasa, and bean sprouts. Mix."}, {"title": "Step 3", "description": "Batter should be thin enough to drop spoonfuls."}, {"title": "Step 4", "description": "Heat oil to 175°C."}, {"title": "Step 5", "description": "Drop tablespoon-sized portions into oil."}, {"title": "Step 6", "description": "Fry 3-4 minutes per side until golden and very crispy."}, {"title": "Step 7", "description": "Drain. Serve with spiced vinegar."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Crispy Pata', 'Grilled/Fried', '40 min', 'Hard', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1450 kcal', 4292932350, '[{"name": "pork leg, cut into a serving portion", "description": "300g pork leg, cut into a serving portion", "amount": "300g", "market_section": "Meat Section", "product_key": "MEAT_PORK_LEG"}, {"name": "salt", "description": "1/2 tsp salt", "amount": "1/2 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT"}, {"name": "pepper", "description": "1/4 tsp pepper", "amount": "1/4 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_PEPPER"}, {"name": "garlic powder", "description": "1/4 tsp garlic powder", "amount": "1/4 tsp", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC_POWDER"}, {"name": "bay leaf", "description": "1 pc bay leaf", "amount": "1 pc", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BAY_LEAF"}, {"name": "peppercorns", "description": "1/4 tsp peppercorns", "amount": "1/4 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_PEPPERCORNS"}, {"name": "Oil for deep-frying", "description": "Oil for deep-frying", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_OIL_FOR_DEEP"}, {"name": "soy sauce and 1 tbsp vinegar with onion and chili for dipping", "description": "1 tbsp soy sauce and 1 tbsp vinegar with onion and chili for dipping", "amount": "1 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_SOY_SAUCE_AND"}]'::jsonb, '[{"title": "Step 1", "description": "Boil pata with bay leaves, peppercorns, and salt for 1.5-2 hours until very tender."}, {"title": "Step 2", "description": "Remove; pat completely dry."}, {"title": "Step 3", "description": "Rub with salt, pepper, and garlic powder."}, {"title": "Step 4", "description": "Air-dry uncovered in refrigerator for at least 8 hours."}, {"title": "Step 5", "description": "Heat deep frying oil to 180°C in a large pot."}, {"title": "Step 6", "description": "Carefully lower pata into oil. Fry 25-30 minutes, basting with oil."}, {"title": "Step 7", "description": "Remove when skin is deeply golden and shatteringly crispy."}, {"title": "Step 8", "description": "Drain; rest 5 minutes. Serve whole with dipping sauce."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Liempo sa Gata', 'Braised', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1650 kcal', 4292932350, '[{"name": "pork belly", "description": "180g pork belly", "amount": "180g", "market_section": "Meat Section", "product_key": "MEAT_PORK_BELLY"}, {"name": "coconut milk", "description": "150ml coconut milk", "amount": "150ml", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_MILK"}, {"name": "coconut cream", "description": "75ml coconut cream", "amount": "75ml", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_CREAM"}, {"name": "siling labuyo", "description": "1 pc siling labuyo", "amount": "1 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_LABUYO"}, {"name": "siling haba", "description": "1 pc siling haba", "amount": "1 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_HABA"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "bagoong alamang", "description": "1 tsp bagoong alamang", "amount": "1 tsp", "market_section": "Fish Section", "product_key": "FISH_BAGOONG_ALAMANG"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Brown pork belly in oil. Remove; set aside."}, {"title": "Step 2", "description": "Sauté garlic and onion in same pan."}, {"title": "Step 3", "description": "Return pork. Add bagoong; stir."}, {"title": "Step 4", "description": "Pour coconut milk. Add all chilis."}, {"title": "Step 5", "description": "Simmer covered 25 minutes until pork is tender."}, {"title": "Step 6", "description": "Add coconut cream. Simmer uncovered until oil separates."}, {"title": "Step 7", "description": "Serve with steamed rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Hardinera', 'Braised', '40 min', 'Hard', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1250 kcal', 4292932350, '[{"name": "ground pork", "description": "150g ground pork", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_GROUND_PORK"}, {"name": "raisins", "description": "1 tbsp raisins", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_RAISINS"}, {"name": "red bell pepper", "description": "1/4 red bell pepper", "amount": "1/4", "market_section": "Dry Goods / Condiments", "product_key": "DRY_RED_BELL_PEPPER"}, {"name": "green peas", "description": "2 tbsp green peas", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_GREEN_PEAS"}, {"name": "hard-boiled egg", "description": "1 hard-boiled egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_HARD_BOILED_EGG"}, {"name": "pineapple tidbits", "description": "1/2 cup pineapple tidbits", "amount": "1/2 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_PINEAPPLE_TIDBITS"}, {"name": "soy sauce", "description": "1 tsp soy sauce", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "gelatin dissolved in 1/4 cup hot broth", "description": "1 tsp gelatin dissolved in 1/4 cup hot broth", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_GELATIN_DISSOLVED_CUP"}]'::jsonb, '[{"title": "Step 1", "description": "Cook ground pork with all vegetables, raisins, soy sauce, and seasoning."}, {"title": "Step 2", "description": "Add pineapple tidbits; cook 2 minutes."}, {"title": "Step 3", "description": "Dissolve gelatin in hot broth; add to pork mixture."}, {"title": "Step 4", "description": "Layer hard-boiled eggs at bottom of greased mold."}, {"title": "Step 5", "description": "Pour pork mixture over eggs."}, {"title": "Step 6", "description": "Steam for 45 minutes."}, {"title": "Step 7", "description": "Cool; refrigerate 3+ hours until set."}, {"title": "Step 8", "description": "Unmold. Slice to reveal eggs. Serve cold."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pork BBQ', 'Grilled/Fried', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1350 kcal', 4292932350, '[{"name": "pork shoulder", "description": "180g pork shoulder", "amount": "180g", "market_section": "Meat Section", "product_key": "MEAT_PORK_SHOULDER"}, {"name": "soy sauce", "description": "1 tbsp soy sauce", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "banana ketchup", "description": "1 tbsp banana ketchup", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BANANA_KETCHUP"}, {"name": "calamansi juice", "description": "1 tbsp calamansi juice", "amount": "1 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_CALAMANSI_JUICE"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "sugar", "description": "1 tsp sugar", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SUGAR"}, {"name": "7-Up or Sprite", "description": "2 tbsp 7-Up or Sprite", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SPRITE"}, {"name": "black pepper", "description": "1/4 tsp black pepper", "amount": "1/4 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BLACK_PEPPER"}, {"name": "bamboo skewers", "description": "4-6 bamboo skewers", "amount": "4-6", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BAMBOO_SKEWERS"}]'::jsonb, '[{"title": "Step 1", "description": "Combine all marinade ingredients. Marinate pork at least 4 hours; overnight is best."}, {"title": "Step 2", "description": "Thread pork strips onto skewers in an ''S'' pattern."}, {"title": "Step 3", "description": "Grill over charcoal on medium heat."}, {"title": "Step 4", "description": "Baste with reserved marinade every 3-4 minutes."}, {"title": "Step 5", "description": "Cook 20-25 minutes, flipping regularly, until cooked with sweet char marks."}, {"title": "Step 6", "description": "Serve with spiced vinegar and steamed rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Chicharon Bulaklak', 'Grilled/Fried', '40 min', 'Hard', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '3200 kcal', 4292932350, '[{"name": "pork mesentery", "description": "150g pork mesentery", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_PORK_MESENTERY"}, {"name": "salt", "description": "1/2 tsp salt", "amount": "1/2 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT"}, {"name": "peppercorns", "description": "1/4 tsp peppercorns", "amount": "1/4 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_PEPPERCORNS"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "bay leaf", "description": "1 pc bay leaf", "amount": "1 pc", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BAY_LEAF"}, {"name": "Oil for deep-frying", "description": "Oil for deep-frying", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_OIL_FOR_DEEP"}, {"name": "spiced vinegar", "description": "2 tbsp spiced vinegar", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SPICED_VINEGAR"}]'::jsonb, '[{"title": "Step 1", "description": "Clean mesentery very thoroughly with salt and vinegar. Rinse."}, {"title": "Step 2", "description": "Boil with garlic, peppercorns, bay leaves, and salt for 1 hour until tender."}, {"title": "Step 3", "description": "Drain; cut into pieces."}, {"title": "Step 4", "description": "Air-dry completely — at least 4 hours or overnight."}, {"title": "Step 5", "description": "Deep-fry at 180°C until puffed, golden, and very crispy."}, {"title": "Step 6", "description": "Drain on rack."}, {"title": "Step 7", "description": "Serve immediately with spiced vinegar."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pinoy Chopsuey', 'Sautéed', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "squid balls", "description": "3 pcs squid balls", "amount": "3 pcs", "market_section": "Fish Section", "product_key": "FISH_SQUID_BALLS"}, {"name": "quail eggs", "description": "2 pcs quail eggs", "amount": "2 pcs", "market_section": "Dry Goods / Condiments", "product_key": "DRY_QUAIL_EGGS"}, {"name": "snap peas", "description": "50g snap peas", "amount": "50g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SNAP_PEAS"}, {"name": "medium carrot", "description": "1/4 medium carrot", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_CARROT"}, {"name": "young corn", "description": "50g young corn", "amount": "50g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_YOUNG_CORN"}, {"name": "mushrooms", "description": "50g mushrooms", "amount": "50g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_MUSHROOMS"}, {"name": "cabbage", "description": "1/8 head cabbage", "amount": "1/8 head", "market_section": "Vegetable Section", "product_key": "VEG_CABBAGE"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "oyster sauce", "description": "1 tbsp oyster sauce", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_OYSTER_SAUCE"}, {"name": "broth", "description": "1/4 cup broth", "amount": "1/4 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BROTH"}, {"name": "cornstarch", "description": "1 tsp cornstarch", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_CORNSTARCH"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Blanch snap peas and carrots briefly. Drain."}, {"title": "Step 2", "description": "Sauté garlic and onion."}, {"title": "Step 3", "description": "Add squid balls; cook until lightly browned."}, {"title": "Step 4", "description": "Add mushrooms and young corn."}, {"title": "Step 5", "description": "Add blanched vegetables and cabbage."}, {"title": "Step 6", "description": "Add quail eggs. Season with oyster sauce."}, {"title": "Step 7", "description": "Add broth; bring to simmer."}, {"title": "Step 8", "description": "Add cornstarch slurry; stir to thicken."}, {"title": "Step 9", "description": "Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Dinengdeng', 'Soup/Stew', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '300 kcal', 4292932350, '[{"name": "bagoong isda", "description": "1 tbsp bagoong isda", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_BAGOONG_ISDA"}, {"name": "water", "description": "1 cup water", "amount": "1 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WATER"}, {"name": "kalabasa", "description": "1/4 cup kalabasa", "amount": "1/4 cup", "market_section": "Vegetable Section", "product_key": "VEG_KALABASA"}, {"name": "ampalaya", "description": "1/4 cup ampalaya", "amount": "1/4 cup", "market_section": "Vegetable Section", "product_key": "VEG_AMPALAYA"}, {"name": "young okra", "description": "1/4 cup young okra", "amount": "1/4 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_YOUNG_OKRA"}, {"name": "eggplant", "description": "1/4 cup eggplant", "amount": "1/4 cup", "market_section": "Vegetable Section", "product_key": "VEG_EGGPLANT"}, {"name": "paria flowers", "description": "1/4 cup paria flowers", "amount": "1/4 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_PARIA_FLOWERS"}, {"name": "grilled or fried fish", "description": "1/2 pc grilled or fried fish", "amount": "1/2 pc", "market_section": "Fish Section", "product_key": "FISH_GRILLED_FRIED_FISH"}]'::jsonb, '[{"title": "Step 1", "description": "Bring water and bagoong isda to a boil."}, {"title": "Step 2", "description": "Add kalabasa; cook 5 minutes."}, {"title": "Step 3", "description": "Add eggplant and ampalaya."}, {"title": "Step 4", "description": "Add okra and paria last."}, {"title": "Step 5", "description": "Add grilled fish."}, {"title": "Step 6", "description": "Simmer until all vegetables are just tender."}, {"title": "Step 7", "description": "Taste — the bagoong provides all the seasoning needed."}, {"title": "Step 8", "description": "Serve with rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Mongo con Hipon', 'Soup/Stew', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '520 kcal', 4292932350, '[{"name": "mung beans", "description": "1/4 cup mung beans", "amount": "1/4 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_MUNG_BEANS"}, {"name": "shrimp", "description": "100g shrimp", "amount": "100g", "market_section": "Fish Section", "product_key": "FISH_SHRIMP"}, {"name": "malunggay leaves", "description": "1/2 cup malunggay leaves", "amount": "1/2 cup", "market_section": "Vegetable Section", "product_key": "VEG_MALUNGGAY_LEAVES"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "medium tomato", "description": "1/2 medium tomato", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_TOMATO"}, {"name": "water", "description": "1 1/2 cups water", "amount": "1 1/2 cups", "market_section": "Dry Goods / Condiments", "product_key": "DRY_CUPS_WATER"}, {"name": "fish sauce", "description": "1 tbsp fish sauce", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Boil soaked mung beans in water until tender (30-40 min)."}, {"title": "Step 2", "description": "In a separate pan, sauté garlic, onion, and tomatoes."}, {"title": "Step 3", "description": "Add shrimp; cook until pink."}, {"title": "Step 4", "description": "Combine with mung beans."}, {"title": "Step 5", "description": "Simmer together 10 minutes."}, {"title": "Step 6", "description": "Add malunggay; cook 2 minutes."}, {"title": "Step 7", "description": "Season with fish sauce. Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pinaputokang Isda', 'Braised', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '950 kcal', 4292932350, '[{"name": "whole tilapia or bangus", "description": "1/2 whole tilapia or bangus", "amount": "1/2", "market_section": "Fish Section", "product_key": "FISH_WHOLE_TILAPIA_BANGUS"}, {"name": "coconut milk", "description": "150ml coconut milk", "amount": "150ml", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_MILK"}, {"name": "1-inch ginger", "description": "1-inch ginger", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_INCH_GINGER"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "medium tomato", "description": "1/2 medium tomato", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_TOMATO"}, {"name": "siling haba", "description": "1 pc siling haba", "amount": "1 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_HABA"}, {"name": "fish sauce", "description": "1 tbsp fish sauce", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE"}]'::jsonb, '[{"title": "Step 1", "description": "Score fish with deep cuts."}, {"title": "Step 2", "description": "Layer ginger, onion, and tomatoes in pot."}, {"title": "Step 3", "description": "Place fish on top."}, {"title": "Step 4", "description": "Pour coconut milk over. Add chilis."}, {"title": "Step 5", "description": "Bring to a boil. Do not stir."}, {"title": "Step 6", "description": "Simmer until coconut milk reduces and fish skin ''bursts'' from the heat (about 20 minutes)."}, {"title": "Step 7", "description": "Season with fish sauce. Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Mechado', 'Braised', '40 min', 'Hard', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '1700 kcal', 4292932350, '[{"name": "beef chuck", "description": "180g beef chuck", "amount": "180g", "market_section": "Meat Section", "product_key": "MEAT_BEEF_CHUCK"}, {"name": "pork fat", "description": "25g pork fat", "amount": "25g", "market_section": "Meat Section", "product_key": "MEAT_PORK_FAT"}, {"name": "tomato sauce", "description": "100g tomato sauce", "amount": "100g", "market_section": "Vegetable Section", "product_key": "VEG_TOMATO_SAUCE"}, {"name": "soy sauce", "description": "1 tbsp soy sauce", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "water", "description": "1/4 cup water", "amount": "1/4 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WATER"}, {"name": "medium potato", "description": "1/2 medium potato", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_POTATO"}, {"name": "medium carrot", "description": "1/2 medium carrot", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_CARROT"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "bay leaf", "description": "1 pc bay leaf", "amount": "1 pc", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BAY_LEAF"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Insert pork fat strips into beef using a skewer or knife, distributing evenly."}, {"title": "Step 2", "description": "Marinate beef in soy sauce 30 minutes."}, {"title": "Step 3", "description": "Brown beef on all sides in hot oil."}, {"title": "Step 4", "description": "Sauté garlic and onion in same pot."}, {"title": "Step 5", "description": "Return beef. Add tomato sauce, soy sauce marinade, water, and bay leaves."}, {"title": "Step 6", "description": "Simmer covered 1.5 hours until very tender."}, {"title": "Step 7", "description": "Add potatoes and carrots. Cook 15 more minutes."}, {"title": "Step 8", "description": "Remove beef; slice. Reduce sauce. Pour over sliced beef."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Sinuglaw', 'Salad/Fresh', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '850 kcal', 4292932350, '[{"name": "pork belly, grilled and chopped", "description": "100g pork belly, grilled and chopped", "amount": "100g", "market_section": "Meat Section", "product_key": "MEAT_PORK_BELLY"}, {"name": "fresh tuna", "description": "100g fresh tuna", "amount": "100g", "market_section": "Fish Section", "product_key": "FISH_FRESH_TUNA"}, {"name": "coconut vinegar", "description": "1 tbsp coconut vinegar", "amount": "1 tbsp", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_VINEGAR"}, {"name": "calamansi juice", "description": "1 tbsp calamansi juice", "amount": "1 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_CALAMANSI_JUICE"}, {"name": "1-inch ginger", "description": "1-inch ginger", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_INCH_GINGER"}, {"name": "red onion", "description": "2 tbsp red onion", "amount": "2 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_RED_ONION"}, {"name": "siling labuyo", "description": "1 pc siling labuyo", "amount": "1 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_LABUYO"}, {"name": "coconut cream", "description": "1 tbsp coconut cream", "amount": "1 tbsp", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_CREAM"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}]'::jsonb, '[{"title": "Step 1", "description": "Grill pork belly until charred and cooked. Chop into small pieces."}, {"title": "Step 2", "description": "Marinate tuna in vinegar and calamansi for 20 minutes."}, {"title": "Step 3", "description": "Drain some liquid from tuna."}, {"title": "Step 4", "description": "Add ginger, onion, and chili to tuna."}, {"title": "Step 5", "description": "Fold in grilled pork."}, {"title": "Step 6", "description": "Add coconut cream; toss."}, {"title": "Step 7", "description": "Season; serve cold."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pyanggang', 'Grilled/Fried', '40 min', 'Hard', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '650 kcal', 4292932350, '[{"name": "chicken pieces", "description": "150g chicken pieces", "amount": "150g", "market_section": "Meat Section", "product_key": "MEAT_CHICKEN_PIECES"}, {"name": "grated coconut, toasted very dark", "description": "1/2 cup grated coconut, toasted very dark", "amount": "1/2 cup", "market_section": "Coconut Section", "product_key": "COCO_GRATED_COCONUT"}, {"name": "turmeric", "description": "1/4 tsp turmeric", "amount": "1/4 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_TURMERIC"}, {"name": "stalk lemongrass", "description": "1 stalk lemongrass", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_STALK_LEMONGRASS"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "1/2-inch ginger", "description": "1/2-inch ginger", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_INCH_GINGER"}, {"name": "siling labuyo", "description": "1 pc siling labuyo", "amount": "1 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_LABUYO"}, {"name": "salt", "description": "1/4 tsp salt", "amount": "1/4 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT"}, {"name": "coconut oil", "description": "1 tsp coconut oil", "amount": "1 tsp", "market_section": "Coconut Section", "product_key": "COCO_COCONUT_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Toast grated coconut in a dry pan, stirring constantly, until very dark brown — almost black."}, {"title": "Step 2", "description": "Cool; blend charred coconut with lemongrass, garlic, ginger, turmeric, and chili."}, {"title": "Step 3", "description": "This becomes a dark paste."}, {"title": "Step 4", "description": "Rub paste generously all over chicken pieces."}, {"title": "Step 5", "description": "Marinate 2-4 hours."}, {"title": "Step 6", "description": "Grill over charcoal until cooked through, basting with coconut oil."}, {"title": "Step 7", "description": "Serve with coconut rice (tiyula)."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginisang Repolyo', 'Sautéed', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '400 kcal', 4292932350, '[{"name": "cabbage", "description": "1/8 head cabbage", "amount": "1/8 head", "market_section": "Vegetable Section", "product_key": "VEG_CABBAGE"}, {"name": "shrimp", "description": "100g shrimp", "amount": "100g", "market_section": "Fish Section", "product_key": "FISH_SHRIMP"}, {"name": "pork", "description": "75g pork", "amount": "75g", "market_section": "Meat Section", "product_key": "MEAT_PORK"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "fish sauce", "description": "1 tbsp fish sauce", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE"}, {"name": "oyster sauce", "description": "1 tsp oyster sauce", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_OYSTER_SAUCE"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil; sauté garlic and onion."}, {"title": "Step 2", "description": "Add pork; cook until done."}, {"title": "Step 3", "description": "Add shrimp; cook until pink."}, {"title": "Step 4", "description": "Add cabbage; stir-fry on high heat."}, {"title": "Step 5", "description": "Season with fish sauce and oyster sauce."}, {"title": "Step 6", "description": "Cook 3-4 minutes until cabbage is just tender but still has bite."}, {"title": "Step 7", "description": "Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Guisadong Toge', 'Sautéed', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '750 kcal', 4292932350, '[{"name": "toge", "description": "200g toge", "amount": "200g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_TOGE"}, {"name": "pork", "description": "75g pork", "amount": "75g", "market_section": "Meat Section", "product_key": "MEAT_PORK"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "fish sauce", "description": "1 tbsp fish sauce", "amount": "1 tbsp", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Rinse and drain bean sprouts. Remove any brown tails."}, {"title": "Step 2", "description": "Heat oil on high heat."}, {"title": "Step 3", "description": "Sauté garlic until golden."}, {"title": "Step 4", "description": "Add onion and pork; cook until pork is done."}, {"title": "Step 5", "description": "Add toge; stir-fry quickly on high heat (1-2 minutes only)."}, {"title": "Step 6", "description": "Season with fish sauce, salt, and pepper."}, {"title": "Step 7", "description": "Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Adobong Sitaw', 'Sautéed', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '900 kcal', 4292932350, '[{"name": "sitaw", "description": "200g sitaw", "amount": "200g", "market_section": "Vegetable Section", "product_key": "VEG_SITAW"}, {"name": "pork belly", "description": "100g pork belly", "amount": "100g", "market_section": "Meat Section", "product_key": "MEAT_PORK_BELLY"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "vinegar", "description": "1 tbsp vinegar", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_VINEGAR"}, {"name": "soy sauce", "description": "1 tsp soy sauce", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "peppercorns", "description": "1/8 tsp peppercorns", "amount": "1/8 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_PEPPERCORNS"}, {"name": "bay leaf", "description": "1 pc bay leaf", "amount": "1 pc", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BAY_LEAF"}, {"name": "cooking oil", "description": "1 tsp cooking oil", "amount": "1 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Sauté garlic in oil until golden."}, {"title": "Step 2", "description": "Add pork; cook until browned."}, {"title": "Step 3", "description": "Add sitaw; stir-fry 2 minutes."}, {"title": "Step 4", "description": "Add vinegar; do not stir for 1 minute."}, {"title": "Step 5", "description": "Add soy sauce, peppercorns, and bay leaves."}, {"title": "Step 6", "description": "Simmer covered 8-10 minutes until sitaw is tender."}, {"title": "Step 7", "description": "Uncover; let sauce slightly reduce."}, {"title": "Step 8", "description": "Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Lumpiang Sariwa', 'Salad/Fresh', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '750 kcal', 4292932350, '[{"name": "For filling: 75g ubod", "description": "For filling: 75g ubod", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_FOR_FILLING_UBOD"}, {"name": "pork", "description": "50g pork", "amount": "50g", "market_section": "Meat Section", "product_key": "MEAT_PORK"}, {"name": "shrimp", "description": "40g shrimp", "amount": "40g", "market_section": "Fish Section", "product_key": "FISH_SHRIMP"}, {"name": "cabbage", "description": "1/2 cup cabbage", "amount": "1/2 cup", "market_section": "Vegetable Section", "product_key": "VEG_CABBAGE"}, {"name": "medium carrot", "description": "1/2 medium carrot", "amount": "1/2", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_CARROT"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "onion", "description": "2 tbsp onion", "amount": "2 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_ONION"}, {"name": "For wrapper: 1 egg, 1/2 cup flour, 3/4 cup water, pinch salt, 1 tsp oil", "description": "For wrapper: 1 egg, 1/2 cup flour, 3/4 cup water, pinch salt, 1 tsp oil", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_FOR_WRAPPER_EGG"}, {"name": "For sauce: 1/3 cup water, 1 tbsp soy sauce, 1 tbsp sugar, 1 tsp cornstarch, 1 clove garlic", "description": "For sauce: 1/3 cup water, 1 tbsp soy sauce, 1 tbsp sugar, 1 tsp cornstarch, 1 clove garlic", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_FOR_SAUCE_CUP"}, {"name": "lettuce leaves", "description": "2 lettuce leaves", "amount": "2", "market_section": "Dry Goods / Condiments", "product_key": "DRY_LETTUCE_LEAVES"}]'::jsonb, '[{"title": "Step 1", "description": "Make wrappers: whisk eggs, flour, water, salt into thin crepe batter. Cook thin crepes in oiled pan. Set aside."}, {"title": "Step 2", "description": "Sauté garlic, onion, pork, shrimp. Add ubod, carrot, cabbage. Season with fish sauce."}, {"title": "Step 3", "description": "Make sauce: cook all sauce ingredients until thick and translucent."}, {"title": "Step 4", "description": "Lay wrapper flat; add lettuce leaf."}, {"title": "Step 5", "description": "Spoon filling onto lettuce."}, {"title": "Step 6", "description": "Roll wrapper around filling."}, {"title": "Step 7", "description": "Drizzle sauce generously over top."}, {"title": "Step 8", "description": "Garnish with crushed peanuts."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pinaupong Manok', 'Braised', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '550 kcal', 4292932350, '[{"name": "chicken pieces", "description": "200g chicken pieces", "amount": "200g", "market_section": "Meat Section", "product_key": "MEAT_CHICKEN_PIECES"}, {"name": "cloves garlic", "description": "3 cloves garlic", "amount": "3", "market_section": "Vegetable Section", "product_key": "VEG_CLOVES_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "1-inch ginger", "description": "1-inch ginger", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_INCH_GINGER"}, {"name": "stalk lemongrass", "description": "1 stalk lemongrass", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_STALK_LEMONGRASS"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "rock salt for the base", "description": "1/4 cup rock salt for the base", "amount": "1/4 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_ROCK_SALT_FOR"}]'::jsonb, '[{"title": "Step 1", "description": "Season chicken inside and out with salt and pepper."}, {"title": "Step 2", "description": "Stuff cavity with garlic, onion, ginger, and lemongrass."}, {"title": "Step 3", "description": "Pour rock salt in bottom of heavy pot or clay pot."}, {"title": "Step 4", "description": "Place stuffed chicken upright on the salt bed."}, {"title": "Step 5", "description": "Cover tightly with foil then lid."}, {"title": "Step 6", "description": "Cook on low heat for 60-75 minutes — no peeking, no water added."}, {"title": "Step 7", "description": "Chicken steams in its own juices."}, {"title": "Step 8", "description": "Rest 10 minutes; serve with the natural juices."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tortang Talong', 'Grilled/Fried', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '300 kcal', 4292932350, '[{"name": "medium talong", "description": "1 medium talong", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_MEDIUM_TALONG"}, {"name": "large egg", "description": "1 large egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_LARGE_EGG"}, {"name": "garlic", "description": "1 clove garlic", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "medium onion", "description": "1/4 medium onion", "amount": "1/4", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_ONION"}, {"name": "Salt and pepper", "description": "Salt and pepper", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "cooking oil", "description": "1 tbsp cooking oil", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Grill or char eggplant over open flame until completely soft."}, {"title": "Step 2", "description": "Peel skin carefully; keep stem intact."}, {"title": "Step 3", "description": "Flatten eggplant with a fork."}, {"title": "Step 4", "description": "Season beaten eggs with garlic, onion, salt, and pepper."}, {"title": "Step 5", "description": "Dip eggplant in egg mixture, letting it absorb."}, {"title": "Step 6", "description": "Pan-fry in hot oil on medium heat until egg is set and golden."}, {"title": "Step 7", "description": "Flip carefully; fry other side."}, {"title": "Step 8", "description": "Serve with banana ketchup or garlic rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tuyo', 'Preserved', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '250 kcal', 4292932350, '[{"name": "tuyo (dried salted herring)", "description": "3-4 pcs tuyo (dried salted herring)", "amount": "3-4 pcs", "market_section": "Fish Section", "product_key": "FISH_TUYO"}, {"name": "cooking oil for frying", "description": "1 tbsp cooking oil for frying", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL_FOR"}, {"name": "white vinegar", "description": "1 tbsp white vinegar", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WHITE_VINEGAR"}, {"name": "siling labuyo, sliced", "description": "1 pc siling labuyo, sliced", "amount": "1 pc", "market_section": "Vegetable Section", "product_key": "VEG_SILING_LABUYO"}, {"name": "garlic, minced (for dip)", "description": "1 clove garlic, minced (for dip)", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}]'::jsonb, '[{"title": "Step 1", "description": "Heat generous oil in pan over medium heat."}, {"title": "Step 2", "description": "Fry tuyo 3-4 minutes per side until very crispy."}, {"title": "Step 3", "description": "Drain on paper towels."}, {"title": "Step 4", "description": "Make dipping vinegar: combine vinegar, garlic, and chili."}, {"title": "Step 5", "description": "Serve tuyo with dipping vinegar and garlic rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tapa', 'Preserved', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "beef sirloin, thinly sliced", "description": "57g beef sirloin, thinly sliced", "amount": "57g", "market_section": "Meat Section", "product_key": "MEAT_BEEF_SIRLOIN"}, {"name": "cloves garlic, minced", "description": "6 cloves garlic, minced", "amount": "6", "market_section": "Vegetable Section", "product_key": "VEG_CLOVES_GARLIC"}, {"name": "soy sauce", "description": "1/3 tsp soy sauce", "amount": "1/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "sugar", "description": "2/3 tsp sugar", "amount": "2/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SUGAR"}, {"name": "calamansi juice", "description": "2/3 tsp calamansi juice", "amount": "2/3 tsp", "market_section": "Vegetable Section", "product_key": "VEG_CALAMANSI_JUICE"}, {"name": "salt", "description": "1/3 tsp salt", "amount": "1/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT"}, {"name": "black pepper", "description": "1/2/3 tsp black pepper", "amount": "1/2/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BLACK_PEPPER"}]'::jsonb, '[{"title": "Step 1", "description": "Slice beef against the grain as thin as possible."}, {"title": "Step 2", "description": "Combine garlic, soy sauce, sugar, calamansi, salt, and pepper."}, {"title": "Step 3", "description": "Toss beef in marinade. Refrigerate 24-48 hours."}, {"title": "Step 4", "description": "Optional: air-dry in fridge uncovered for another 24 hours."}, {"title": "Step 5", "description": "Pan-fry in minimal oil over medium-high heat until browned."}, {"title": "Step 6", "description": "Serve as tapsilog: with sinangag (garlic rice) and itlog (fried egg)."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tapsilog', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "beef sirloin, thinly sliced", "description": "57g beef sirloin, thinly sliced", "amount": "57g", "market_section": "Meat Section", "product_key": "MEAT_BEEF_SIRLOIN"}, {"name": "soy sauce", "description": "1/3 tsp soy sauce", "amount": "1/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "calamansi juice", "description": "2/3 tsp calamansi juice", "amount": "2/3 tsp", "market_section": "Vegetable Section", "product_key": "VEG_CALAMANSI_JUICE"}, {"name": "brown sugar", "description": "1/3 tsp brown sugar", "amount": "1/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BROWN_SUGAR"}, {"name": "garlic, minced", "description": "1 clove garlic, minced", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "ground black pepper", "description": "1/6 tsp ground black pepper", "amount": "1/6 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_GROUND_BLACK_PEPPER"}, {"name": "cooking oil", "description": "2/3 tsp cooking oil", "amount": "2/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "garlic fried rice", "description": "1/3 cup garlic fried rice", "amount": "1/3 cup", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC_FRIED_RICE"}, {"name": "egg", "description": "1 egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGG"}]'::jsonb, '[{"title": "Step 1", "description": "Marinate the beef with soy sauce, calamansi juice, brown sugar, garlic, and black pepper for at least 4 hours or overnight."}, {"title": "Step 2", "description": "Heat oil in a frying pan over medium heat."}, {"title": "Step 3", "description": "Fry the marinated beef until browned and cooked through."}, {"title": "Step 4", "description": "In another pan, cook the sunny-side-up eggs."}, {"title": "Step 5", "description": "Reheat or prepare the garlic fried rice."}, {"title": "Step 6", "description": "Arrange the garlic rice, beef tapa, and egg on a serving plate."}, {"title": "Step 7", "description": "Serve hot with sliced tomatoes or pickled papaya (atchara)."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Longsilog', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "pieces pork longganisa", "description": "1 pieces pork longganisa", "amount": "1", "market_section": "Meat Section", "product_key": "MEAT_PIECES_PORK_LONGGANISA"}, {"name": "garlic fried rice", "description": "1/3 cup garlic fried rice", "amount": "1/3 cup", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC_FRIED_RICE"}, {"name": "egg", "description": "1 egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGG"}, {"name": "cooking oil", "description": "1/3 tsp cooking oil", "amount": "1/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Sliced tomatoes (optional)", "description": "Sliced tomatoes (optional)", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_SLICED_TOMATOES"}]'::jsonb, '[{"title": "Step 1", "description": "Heat a pan over medium heat and add the longganisa."}, {"title": "Step 2", "description": "Pour in ¼ cup water and cover the pan."}, {"title": "Step 3", "description": "Cook until the water evaporates."}, {"title": "Step 4", "description": "Add the cooking oil and fry the longganisa until browned."}, {"title": "Step 5", "description": "Fry the eggs to your preferred doneness."}, {"title": "Step 6", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 7", "description": "Serve together with sliced tomatoes."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tosilog', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "pork tocino", "description": "57g pork tocino", "amount": "57g", "market_section": "Meat Section", "product_key": "MEAT_PORK_TOCINO"}, {"name": "garlic fried rice", "description": "1/3 cup garlic fried rice", "amount": "1/3 cup", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC_FRIED_RICE"}, {"name": "egg", "description": "1 egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGG"}, {"name": "cooking oil", "description": "1/3 tsp cooking oil", "amount": "1/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Cucumber or tomato slices", "description": "Cucumber or tomato slices", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_CUCUMBER_TOMATO_SLICES"}]'::jsonb, '[{"title": "Step 1", "description": "Place the tocino in a pan with ¼ cup water."}, {"title": "Step 2", "description": "Cook until the water evaporates."}, {"title": "Step 3", "description": "Add oil and fry until lightly caramelized."}, {"title": "Step 4", "description": "Cook the eggs until desired doneness."}, {"title": "Step 5", "description": "Prepare the garlic fried rice."}, {"title": "Step 6", "description": "Arrange the tocino, rice, and egg on a serving plate."}, {"title": "Step 7", "description": "Serve immediately with fresh vegetables."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Bangsilog', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "boneless milkfish (bangus)", "description": "2 boneless milkfish (bangus)", "amount": "2", "market_section": "Fish Section", "product_key": "FISH_BONELESS_MILKFISH"}, {"name": "Salt and pepper to taste", "description": "Salt and pepper to taste", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "cooking oil", "description": "2/3 tsp cooking oil", "amount": "2/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "garlic fried rice", "description": "1/3 cup garlic fried rice", "amount": "1/3 cup", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC_FRIED_RICE"}, {"name": "egg", "description": "1 egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGG"}]'::jsonb, '[{"title": "Step 1", "description": "Season the bangus with salt and pepper."}, {"title": "Step 2", "description": "Heat oil in a frying pan."}, {"title": "Step 3", "description": "Fry the bangus until crispy on both sides."}, {"title": "Step 4", "description": "Remove and drain on paper towels."}, {"title": "Step 5", "description": "Fry the eggs."}, {"title": "Step 6", "description": "Prepare the garlic fried rice."}, {"title": "Step 7", "description": "Serve hot with vinegar dipping sauce."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Corned Beef Silog', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "corned beef", "description": "1/2 can corned beef", "amount": "1/2 can", "market_section": "Meat Section", "product_key": "MEAT_CORNED_BEEF"}, {"name": "onion, chopped", "description": "1/3 onion, chopped", "amount": "1/3", "market_section": "Vegetable Section", "product_key": "VEG_ONION"}, {"name": "garlic, minced", "description": "1 clove garlic, minced", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "cooking oil", "description": "1/3 tsp cooking oil", "amount": "1/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "garlic fried rice", "description": "1/3 cup garlic fried rice", "amount": "1/3 cup", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC_FRIED_RICE"}, {"name": "egg", "description": "1 egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGG"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil in a pan and sauté the garlic and onion."}, {"title": "Step 2", "description": "Add the corned beef and cook for 5–7 minutes."}, {"title": "Step 3", "description": "Stir occasionally until heated through."}, {"title": "Step 4", "description": "Fry the eggs separately."}, {"title": "Step 5", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 6", "description": "Plate the corned beef, rice, and egg together."}, {"title": "Step 7", "description": "Serve while hot."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Daingsilog', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "pieces dried fish (daing)", "description": "1.3 pieces dried fish (daing)", "amount": "1.3", "market_section": "Fish Section", "product_key": "FISH_PIECES_DRIED_FISH"}, {"name": "cooking oil", "description": "2/3 tsp cooking oil", "amount": "2/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "garlic fried rice", "description": "1/3 cup garlic fried rice", "amount": "1/3 cup", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC_FRIED_RICE"}, {"name": "egg", "description": "1 egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGG"}, {"name": "Vinegar for dipping", "description": "Vinegar for dipping", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_VINEGAR_FOR_DIPPING"}]'::jsonb, '[{"title": "Step 1", "description": "Rinse the dried fish briefly and pat dry."}, {"title": "Step 2", "description": "Heat oil over medium heat."}, {"title": "Step 3", "description": "Fry the dried fish until crispy."}, {"title": "Step 4", "description": "Fry the eggs separately."}, {"title": "Step 5", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 6", "description": "Arrange everything on a serving plate."}, {"title": "Step 7", "description": "Serve with vinegar dipping sauce. Servings: 1 personx`"}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Champorado', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "glutinous rice", "description": "1/1 cup glutinous rice", "amount": "1/1 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_GLUTINOUS_RICE"}, {"name": "water", "description": "1 2/1 cups water", "amount": "1 2/1 cups", "market_section": "Dry Goods / Condiments", "product_key": "DRY_CUPS_WATER"}, {"name": "cocoa powder or tablea", "description": "1/6 cup cocoa powder or tablea", "amount": "1/6 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COCOA_POWDER_TABLEA"}, {"name": "sugar", "description": "1/6 cup sugar", "amount": "1/6 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SUGAR"}, {"name": "evaporated milk", "description": "1/6 cup evaporated milk", "amount": "1/6 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EVAPORATED_MILK"}]'::jsonb, '[{"title": "Step 1", "description": "Wash the glutinous rice thoroughly."}, {"title": "Step 2", "description": "Bring the water to a boil in a pot."}, {"title": "Step 3", "description": "Add the rice and cook until tender."}, {"title": "Step 4", "description": "Stir in the cocoa powder or melted tablea."}, {"title": "Step 5", "description": "Add the sugar and mix well."}, {"title": "Step 6", "description": "Simmer until the porridge thickens. Servings: 1 person"}, {"title": "Step 7", "description": "Serve warm with evaporated milk drizzled on top."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Arroz Caldo', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "glutinous rice", "description": "1/1 cup glutinous rice", "amount": "1/1 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_GLUTINOUS_RICE"}, {"name": "chicken, cut into serving pieces", "description": "57g chicken, cut into serving pieces", "amount": "57g", "market_section": "Meat Section", "product_key": "MEAT_CHICKEN"}, {"name": "chicken broth", "description": "2/3 cups chicken broth", "amount": "2/3 cups", "market_section": "Meat Section", "product_key": "MEAT_CUPS_CHICKEN_BROTH"}, {"name": "onion, chopped", "description": "1/3 onion, chopped", "amount": "1/3", "market_section": "Vegetable Section", "product_key": "VEG_ONION"}, {"name": "garlic, minced", "description": "1 clove garlic, minced", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "thumb-sized ginger, julienned", "description": "1/3 thumb-sized ginger, julienned", "amount": "1/3", "market_section": "Vegetable Section", "product_key": "VEG_THUMB_SIZED_GINGER"}, {"name": "fish sauce", "description": "2/3 tsp fish sauce", "amount": "2/3 tsp", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE"}, {"name": "cooking oil", "description": "2/3 tsp cooking oil", "amount": "2/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Chopped spring onions and boiled eggs for garnish", "description": "Chopped spring onions and boiled eggs for garnish", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_CHOPPED_SPRING_ONIONS"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil and sauté the garlic, onion, and ginger until fragrant."}, {"title": "Step 2", "description": "Add the chicken and cook until lightly browned."}, {"title": "Step 3", "description": "Stir in the fish sauce."}, {"title": "Step 4", "description": "Add the glutinous rice and chicken broth."}, {"title": "Step 5", "description": "Bring to a boil, then simmer until the rice is soft and the porridge thickens. Servings: 1 person"}, {"title": "Step 6", "description": "Taste and adjust the seasoning if needed."}, {"title": "Step 7", "description": "Garnish with spring onions and boiled eggs before serving."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Hotsilog', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "Filipino-style hotdogs", "description": "3 Filipino-style hotdogs", "amount": "3", "market_section": "Dry Goods / Condiments", "product_key": "DRY_FILIPINO_STYLE_HOTDOGS"}, {"name": "garlic fried rice", "description": "1/3 cup garlic fried rice", "amount": "1/3 cup", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC_FRIED_RICE"}, {"name": "egg", "description": "1 egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGG"}, {"name": "cooking oil", "description": "1/3 tsp cooking oil", "amount": "1/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Banana ketchup for serving", "description": "Banana ketchup for serving", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BANANA_KETCHUP_FOR"}]'::jsonb, '[{"title": "Step 1", "description": "Heat the cooking oil in a frying pan over medium heat."}, {"title": "Step 2", "description": "Fry the hotdogs for 5–7 minutes, turning occasionally until evenly browned."}, {"title": "Step 3", "description": "Remove the hotdogs and set aside."}, {"title": "Step 4", "description": "Fry the eggs until cooked to your preferred doneness. Servings: 1 person"}, {"title": "Step 5", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 6", "description": "Arrange the hotdogs, garlic rice, and fried egg on a serving plate."}, {"title": "Step 7", "description": "Serve hot with banana ketchup."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Spam Silog', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "slices Spam", "description": "3 slices Spam", "amount": "3", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SLICES_SPAM"}, {"name": "garlic fried rice", "description": "1/3 cup garlic fried rice", "amount": "1/3 cup", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC_FRIED_RICE"}, {"name": "egg", "description": "1 egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGG"}, {"name": "cooking oil", "description": "1/3 tsp cooking oil", "amount": "1/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil in a frying pan over medium heat."}, {"title": "Step 2", "description": "Fry the Spam slices for 2–3 minutes on each side until lightly crispy."}, {"title": "Step 3", "description": "Remove and drain excess oil. Servings: 1 person"}, {"title": "Step 4", "description": "Fry the eggs separately."}, {"title": "Step 5", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 6", "description": "Arrange the Spam, rice, and egg on a serving plate."}, {"title": "Step 7", "description": "Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Chicken Adobo Silog', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "cooked chicken adobo", "description": "2/1 cup cooked chicken adobo", "amount": "2/1 cup", "market_section": "Meat Section", "product_key": "MEAT_COOKED_CHICKEN_ADOBO"}, {"name": "garlic fried rice", "description": "1/3 cup garlic fried rice", "amount": "1/3 cup", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC_FRIED_RICE"}, {"name": "egg", "description": "1 egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGG"}, {"name": "cooking oil", "description": "1/3 tsp cooking oil", "amount": "1/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Heat the chicken adobo in a pan until warmed through."}, {"title": "Step 2", "description": "Fry the chicken pieces lightly for crispier edges if desired. Servings: 1 person"}, {"title": "Step 3", "description": "Cook the eggs to your preferred doneness."}, {"title": "Step 4", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 5", "description": "Arrange the chicken adobo, garlic rice, and egg on a serving plate."}, {"title": "Step 6", "description": "Spoon some adobo sauce over the rice if desired."}, {"title": "Step 7", "description": "Serve hot."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Goto', 'Breakfast', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "beef tripe, cleaned and boiled until tender", "description": "500g beef tripe, cleaned and boiled until tender", "amount": "500g", "market_section": "Meat Section", "product_key": "MEAT_BEEF_TRIPE"}, {"name": "glutinous rice", "description": "1 cup glutinous rice", "amount": "1 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_GLUTINOUS_RICE"}, {"name": "beef broth", "description": "6 cups beef broth", "amount": "6 cups", "market_section": "Meat Section", "product_key": "MEAT_CUPS_BEEF_BROTH"}, {"name": "onion, chopped", "description": "1 onion, chopped", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_ONION"}, {"name": "cloves garlic, minced", "description": "5 cloves garlic, minced", "amount": "5", "market_section": "Vegetable Section", "product_key": "VEG_CLOVES_GARLIC"}, {"name": "thumb-sized ginger, julienned", "description": "1 thumb-sized ginger, julienned", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_THUMB_SIZED_GINGER"}, {"name": "fish sauce", "description": "2 tbsp fish sauce", "amount": "2 tbsp", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE"}, {"name": "cooking oil", "description": "2 tbsp cooking oil", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Fried garlic and chopped spring onions for garnish", "description": "Fried garlic and chopped spring onions for garnish", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_FRIED_GARLIC_AND"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil and sauté the garlic, onion, and ginger until fragrant. Servings: 1 person"}, {"title": "Step 2", "description": "Add the cooked beef tripe and stir for 2–3 minutes."}, {"title": "Step 3", "description": "Add the glutinous rice and beef broth."}, {"title": "Step 4", "description": "Bring to a boil, then simmer until the rice becomes soft and creamy."}, {"title": "Step 5", "description": "Stir in the fish sauce and cook for another 5 minutes."}, {"title": "Step 6", "description": "Adjust the seasoning if needed."}, {"title": "Step 7", "description": "Garnish with fried garlic and spring onions before serving."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Beef Pares with Garlic Rice', 'Breakfast', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "beef brisket, cubed", "description": "500g beef brisket, cubed", "amount": "500g", "market_section": "Meat Section", "product_key": "MEAT_BEEF_BRISKET"}, {"name": "cloves garlic, minced", "description": "4 cloves garlic, minced", "amount": "4", "market_section": "Vegetable Section", "product_key": "VEG_CLOVES_GARLIC"}, {"name": "onion, chopped", "description": "1 onion, chopped", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_ONION"}, {"name": "¼ cup soy sauce", "description": "¼ cup soy sauce", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_CUP_SOY_SAUCE"}, {"name": "brown sugar", "description": "2 tbsp brown sugar", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BROWN_SUGAR"}, {"name": "beef broth", "description": "4 cups beef broth", "amount": "4 cups", "market_section": "Meat Section", "product_key": "MEAT_CUPS_BEEF_BROTH"}, {"name": "star anise", "description": "1 star anise", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_STAR_ANISE"}, {"name": "garlic fried rice", "description": "3 cups garlic fried rice", "amount": "3 cups", "market_section": "Vegetable Section", "product_key": "VEG_CUPS_GARLIC_FRIED"}, {"name": "Steps Servings: 1 person", "description": "Steps Servings: 1 person", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_STEPS_SERVINGS_PERSON"}, {"name": "Sauté the garlic and onion until fragrant.", "description": "Sauté the garlic and onion until fragrant.", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_THE_GARLIC_AND"}, {"name": "Add the beef and cook until lightly browned.", "description": "Add the beef and cook until lightly browned.", "amount": "1 serving", "market_section": "Meat Section", "product_key": "MEAT_ADD_THE_BEEF"}, {"name": "Stir in the soy sauce, brown sugar, beef broth, and star anise.", "description": "Stir in the soy sauce, brown sugar, beef broth, and star anise.", "amount": "1 serving", "market_section": "Meat Section", "product_key": "MEAT_STIR_THE_SOY"}, {"name": "Simmer for 1½–2 hours until the beef is tender.", "description": "Simmer for 1½–2 hours until the beef is tender.", "amount": "1 serving", "market_section": "Meat Section", "product_key": "MEAT_SIMMER_FOR_HOURS"}, {"name": "Reduce the sauce until slightly thickened.", "description": "Reduce the sauce until slightly thickened.", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_REDUCE_THE_SAUCE"}, {"name": "Prepare the garlic fried rice.", "description": "Prepare the garlic fried rice.", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_PREPARE_THE_GARLIC"}, {"name": "Serve the beef pares over or beside the rice.", "description": "Serve the beef pares over or beside the rice.", "amount": "1 serving", "market_section": "Meat Section", "product_key": "MEAT_SERVE_THE_BEEF"}]'::jsonb, '[]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tinapang Bangus with Garlic Rice', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "smoked milkfish (tinapang bangus)", "description": "2 smoked milkfish (tinapang bangus)", "amount": "2", "market_section": "Fish Section", "product_key": "FISH_SMOKED_MILKFISH"}, {"name": "cooking oil", "description": "1 tbsp cooking oil", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "garlic fried rice", "description": "3 cups garlic fried rice", "amount": "3 cups", "market_section": "Vegetable Section", "product_key": "VEG_CUPS_GARLIC_FRIED"}, {"name": "eggs", "description": "3 eggs", "amount": "3", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGGS"}, {"name": "Vinegar for dipping Servings: 1 person", "description": "Vinegar for dipping Servings: 1 person", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_VINEGAR_FOR_DIPPING"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil in a frying pan."}, {"title": "Step 2", "description": "Fry the smoked milkfish until heated through and slightly crispy."}, {"title": "Step 3", "description": "Fry the eggs separately."}, {"title": "Step 4", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 5", "description": "Arrange the fish, rice, and egg on a serving plate."}, {"title": "Step 6", "description": "Serve with sliced tomatoes."}, {"title": "Step 7", "description": "Enjoy with vinegar dipping sauce."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Sardinas Silog', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "cans sardines in tomato sauce", "description": "2 cans sardines in tomato sauce", "amount": "2", "market_section": "Vegetable Section", "product_key": "VEG_CANS_SARDINES_TOMATO"}, {"name": "onion, chopped", "description": "1 onion, chopped", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_ONION"}, {"name": "cloves garlic, minced", "description": "3 cloves garlic, minced", "amount": "3", "market_section": "Vegetable Section", "product_key": "VEG_CLOVES_GARLIC"}, {"name": "cooking oil", "description": "1 tbsp cooking oil", "amount": "1 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "garlic fried rice Servings: 1 person", "description": "3 cups garlic fried rice Servings: 1 person", "amount": "3 cups", "market_section": "Vegetable Section", "product_key": "VEG_CUPS_GARLIC_FRIED"}, {"name": "eggs", "description": "3 eggs", "amount": "3", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGGS"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil and sauté the garlic and onion until fragrant."}, {"title": "Step 2", "description": "Add the canned sardines with the sauce."}, {"title": "Step 3", "description": "Simmer for 5 minutes."}, {"title": "Step 4", "description": "Fry the eggs separately."}, {"title": "Step 5", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 6", "description": "Plate the sardines, rice, and egg together."}, {"title": "Step 7", "description": "Serve hot."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Lugaw', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "white rice", "description": "1 cup white rice", "amount": "1 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WHITE_RICE"}, {"name": "chicken broth or water", "description": "7 cups chicken broth or water", "amount": "7 cups", "market_section": "Meat Section", "product_key": "MEAT_CUPS_CHICKEN_BROTH"}, {"name": "onion, chopped", "description": "1 onion, chopped", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_ONION"}, {"name": "cloves garlic, minced", "description": "4 cloves garlic, minced", "amount": "4", "market_section": "Vegetable Section", "product_key": "VEG_CLOVES_GARLIC"}, {"name": "thumb-sized ginger, sliced", "description": "1 thumb-sized ginger, sliced", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_THUMB_SIZED_GINGER"}, {"name": "fish sauce Servings: 1 person", "description": "2 tbsp fish sauce Servings: 1 person", "amount": "2 tbsp", "market_section": "Fish Section", "product_key": "FISH_FISH_SAUCE_SERVINGS"}, {"name": "cooking oil", "description": "2 tbsp cooking oil", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Fried garlic, chopped spring onions, and boiled eggs for garnish", "description": "Fried garlic, chopped spring onions, and boiled eggs for garnish", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_FRIED_GARLIC"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil and sauté the garlic, onion, and ginger until fragrant."}, {"title": "Step 2", "description": "Add the rice and stir for 2 minutes."}, {"title": "Step 3", "description": "Pour in the chicken broth or water and bring to a boil."}, {"title": "Step 4", "description": "Reduce the heat and simmer for 30–40 minutes, stirring occasionally until the rice breaks down into a creamy porridge."}, {"title": "Step 5", "description": "Stir in the fish sauce and adjust the seasoning."}, {"title": "Step 6", "description": "Ladle the lugaw into serving bowls."}, {"title": "Step 7", "description": "Garnish with fried garlic, spring onions, and boiled eggs before serving."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Dangsilog', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "pieces dried danggit", "description": "8 pieces dried danggit", "amount": "8", "market_section": "Dry Goods / Condiments", "product_key": "DRY_PIECES_DRIED_DANGGIT"}, {"name": "cooking oil", "description": "2 tbsp cooking oil", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "garlic fried rice Servings: 1 person", "description": "3 cups garlic fried rice Servings: 1 person", "amount": "3 cups", "market_section": "Vegetable Section", "product_key": "VEG_CUPS_GARLIC_FRIED"}, {"name": "eggs", "description": "3 eggs", "amount": "3", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGGS"}, {"name": "Vinegar for dipping", "description": "Vinegar for dipping", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_VINEGAR_FOR_DIPPING"}, {"name": "Sliced tomatoes (optional)", "description": "Sliced tomatoes (optional)", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_SLICED_TOMATOES"}]'::jsonb, '[{"title": "Step 1", "description": "Rinse the danggit quickly under running water and pat dry."}, {"title": "Step 2", "description": "Heat the cooking oil over medium heat."}, {"title": "Step 3", "description": "Fry the danggit until crispy and golden brown."}, {"title": "Step 4", "description": "Remove and drain on paper towels."}, {"title": "Step 5", "description": "Fry the eggs to your desired doneness."}, {"title": "Step 6", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 7", "description": "Serve the danggit with garlic rice, egg, tomatoes, and vinegar."}]'::jsonb);
