INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginisang Sardinas with Pandesal', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "sardines in tomato sauce", "description": "1/2 can sardines in tomato sauce", "amount": "1/2 can", "market_section": "Vegetable Section", "product_key": "VEG_SARDINES_TOMATO_SAUCE"}, {"name": "onion, chopped", "description": "1/3 onion, chopped", "amount": "1/3", "market_section": "Vegetable Section", "product_key": "VEG_ONION"}, {"name": "garlic, minced", "description": "1 clove garlic, minced", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "cooking oil", "description": "1/3 tsp cooking oil", "amount": "1/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "pieces pandesal", "description": "2/3 pieces pandesal", "amount": "2/3", "market_section": "Dry Goods / Condiments", "product_key": "DRY_PIECES_PANDESAL"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil and sauté the garlic until fragrant."}, {"title": "Step 2", "description": "Add the onion and cook until translucent."}, {"title": "Step 3", "description": "Pour in the canned sardines with the sauce."}, {"title": "Step 4", "description": "Simmer for 5 minutes."}, {"title": "Step 5", "description": "Warm the pandesal in the oven or toaster."}, {"title": "Step 6", "description": "Transfer the sardines to a serving bowl."}, {"title": "Step 7", "description": "Serve hot with warm pandesal."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tuyo Silog', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '500 kcal', 4292932350, '[{"name": "pieces tuyo (dried herring)", "description": "3-1.3 pieces tuyo (dried herring)", "amount": "3-1.3", "market_section": "Fish Section", "product_key": "FISH_PIECES_TUYO"}, {"name": "cooking oil", "description": "2/3 tsp cooking oil", "amount": "2/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "garlic fried rice", "description": "1/3 cup garlic fried rice", "amount": "1/3 cup", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC_FRIED_RICE"}, {"name": "egg", "description": "1 egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGG"}, {"name": "Vinegar for dipping", "description": "Vinegar for dipping", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_VINEGAR_FOR_DIPPING"}]'::jsonb, '[{"title": "Step 1", "description": "Heat the cooking oil in a frying pan."}, {"title": "Step 2", "description": "Fry the tuyo until crispy."}, {"title": "Step 3", "description": "Remove and drain excess oil."}, {"title": "Step 4", "description": "Fry the eggs separately."}, {"title": "Step 5", "description": "Prepare the garlic fried rice."}, {"title": "Step 6", "description": "Arrange everything on a serving plate."}, {"title": "Step 7", "description": "Serve with vinegar and sliced tomatoes."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginisang Corned Tuna with Rice', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "corned tuna", "description": "1 can corned tuna", "amount": "1 can", "market_section": "Fish Section", "product_key": "FISH_CORNED_TUNA"}, {"name": "onion, chopped", "description": "1/3 onion, chopped", "amount": "1/3", "market_section": "Vegetable Section", "product_key": "VEG_ONION"}, {"name": "garlic, minced", "description": "1 clove garlic, minced", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "cooking oil", "description": "1/3 tsp cooking oil", "amount": "1/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "steamed rice", "description": "1/3 cup steamed rice", "amount": "1/3 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_STEAMED_RICE"}, {"name": "Ground black pepper to taste", "description": "Ground black pepper to taste", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_GROUND_BLACK_PEPPER"}]'::jsonb, '[{"title": "Step 1", "description": "Heat the cooking oil in a pan."}, {"title": "Step 2", "description": "Sauté the garlic and onion until fragrant."}, {"title": "Step 3", "description": "Add the corned tuna and cook for 5 minutes."}, {"title": "Step 4", "description": "Season with black pepper."}, {"title": "Step 5", "description": "Prepare warm steamed rice."}, {"title": "Step 6", "description": "Spoon the tuna over the rice."}, {"title": "Step 7", "description": "Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Chicken Tocino Silog', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "chicken tocino", "description": "57g chicken tocino", "amount": "57g", "market_section": "Meat Section", "product_key": "MEAT_CHICKEN_TOCINO"}, {"name": "garlic fried rice", "description": "1/3 cup garlic fried rice", "amount": "1/3 cup", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC_FRIED_RICE"}, {"name": "egg", "description": "1 egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGG"}, {"name": "cooking oil", "description": "1/3 tsp cooking oil", "amount": "1/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}]'::jsonb, '[{"title": "Step 1", "description": "Place the chicken tocino in a pan with a small amount of water."}, {"title": "Step 2", "description": "Cook until the water evaporates."}, {"title": "Step 3", "description": "Add the oil and fry until lightly caramelized."}, {"title": "Step 4", "description": "Fry the eggs separately."}, {"title": "Step 5", "description": "Prepare the garlic fried rice."}, {"title": "Step 6", "description": "Arrange the chicken tocino, rice, and egg on a plate."}, {"title": "Step 7", "description": "Serve hot."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tortang Talong with Garlic Rice', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '350 kcal', 4292932350, '[{"name": "large eggplant", "description": "1 large eggplant", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_LARGE_EGGPLANT"}, {"name": "egg, beaten", "description": "1 egg, beaten", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGG"}, {"name": "garlic, minced", "description": "1 clove garlic, minced", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "Salt and ground black pepper to taste", "description": "Salt and ground black pepper to taste", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_GROUND"}, {"name": "cooking oil", "description": "2/3 tsp cooking oil", "amount": "2/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "garlic fried rice", "description": "1/3 cup garlic fried rice", "amount": "1/3 cup", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC_FRIED_RICE"}]'::jsonb, '[{"title": "Step 1", "description": "Grill the eggplants until the skin is charred and the flesh is tender."}, {"title": "Step 2", "description": "Peel off the skin while keeping the stem intact."}, {"title": "Step 3", "description": "Flatten each eggplant gently with a fork."}, {"title": "Step 4", "description": "Season with salt and pepper, then dip in the beaten eggs."}, {"title": "Step 5", "description": "Heat the oil and fry each eggplant until golden brown on both sides."}, {"title": "Step 6", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 7", "description": "Serve hot with garlic rice and banana ketchup."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Beef Tapa with Garlic Rice and Atchara', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "beef sirloin, thinly sliced", "description": "57g beef sirloin, thinly sliced", "amount": "57g", "market_section": "Meat Section", "product_key": "MEAT_BEEF_SIRLOIN"}, {"name": "soy sauce", "description": "1/3 tsp soy sauce", "amount": "1/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "calamansi juice", "description": "2/3 tsp calamansi juice", "amount": "2/3 tsp", "market_section": "Vegetable Section", "product_key": "VEG_CALAMANSI_JUICE"}, {"name": "brown sugar", "description": "1/3 tsp brown sugar", "amount": "1/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BROWN_SUGAR"}, {"name": "garlic, minced", "description": "1-1 clove garlic, minced", "amount": "1-1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "ground black pepper", "description": "1/6 tsp ground black pepper", "amount": "1/6 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_GROUND_BLACK_PEPPER"}, {"name": "cooking oil", "description": "2/3 tsp cooking oil", "amount": "2/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "garlic fried rice", "description": "1/3 cup garlic fried rice", "amount": "1/3 cup", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC_FRIED_RICE"}, {"name": "egg", "description": "1 egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGG"}, {"name": "Atchara for serving", "description": "Atchara for serving", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_ATCHARA_FOR_SERVING"}]'::jsonb, '[{"title": "Step 1", "description": "Marinate the beef with soy sauce, calamansi juice, brown sugar, garlic, and black pepper for at least 4 hours."}, {"title": "Step 2", "description": "Heat the cooking oil in a frying pan over medium heat."}, {"title": "Step 3", "description": "Fry the marinated beef until browned and fully cooked."}, {"title": "Step 4", "description": "Fry the eggs to your preferred doneness."}, {"title": "Step 5", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 6", "description": "Arrange the beef tapa, garlic rice, and fried egg on a serving plate."}, {"title": "Step 7", "description": "Serve with atchara on the side."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pork Steak Silog', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "pork chops", "description": "57g pork chops", "amount": "57g", "market_section": "Meat Section", "product_key": "MEAT_PORK_CHOPS"}, {"name": "soy sauce", "description": "1/3 tsp soy sauce", "amount": "1/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "calamansi juice", "description": "1/3 tbsp calamansi juice", "amount": "1/3 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_CALAMANSI_JUICE"}, {"name": "onion, sliced into rings", "description": "1/3 onion, sliced into rings", "amount": "1/3", "market_section": "Vegetable Section", "product_key": "VEG_ONION"}, {"name": "garlic, minced", "description": "1-1 clove garlic, minced", "amount": "1-1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "cooking oil", "description": "2/3 tsp cooking oil", "amount": "2/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "garlic fried rice", "description": "1/3 cup garlic fried rice", "amount": "1/3 cup", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC_FRIED_RICE"}, {"name": "egg", "description": "1 egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGG"}]'::jsonb, '[{"title": "Step 1", "description": "Marinate the pork in soy sauce, calamansi juice, and garlic for at least 1 hour."}, {"title": "Step 2", "description": "Heat the oil and fry the pork until cooked through."}, {"title": "Step 3", "description": "Remove the pork and sauté the onion rings until tender."}, {"title": "Step 4", "description": "Return the pork to the pan and cook for another 2 minutes."}, {"title": "Step 5", "description": "Fry the eggs separately."}, {"title": "Step 6", "description": "Prepare the garlic fried rice."}, {"title": "Step 7", "description": "Serve the pork steak with garlic rice and fried egg."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginisang Corned Beef with Potato', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '350 kcal', 4292932350, '[{"name": "corned beef", "description": "1/2 can corned beef", "amount": "1/2 can", "market_section": "Meat Section", "product_key": "MEAT_CORNED_BEEF"}, {"name": "medium potato, diced", "description": "1 medium potato, diced", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_MEDIUM_POTATO"}, {"name": "onion, chopped", "description": "1/3 onion, chopped", "amount": "1/3", "market_section": "Vegetable Section", "product_key": "VEG_ONION"}, {"name": "garlic, minced", "description": "1 clove garlic, minced", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "cooking oil", "description": "2/3 tsp cooking oil", "amount": "2/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Salt and pepper to taste", "description": "Salt and pepper to taste", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "steamed rice", "description": "1/3 cup steamed rice", "amount": "1/3 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_STEAMED_RICE"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil in a frying pan."}, {"title": "Step 2", "description": "Fry the diced potatoes until lightly browned."}, {"title": "Step 3", "description": "Add the garlic and onion and sauté until fragrant."}, {"title": "Step 4", "description": "Stir in the corned beef and cook for 5–7 minutes."}, {"title": "Step 5", "description": "Season with salt and pepper."}, {"title": "Step 6", "description": "Prepare warm rice."}, {"title": "Step 7", "description": "Serve hot with rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Fried Galunggong Silog', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '350 kcal', 4292932350, '[{"name": "whole galunggong, cleaned", "description": "1 whole galunggong, cleaned", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_WHOLE_GALUNGGONG"}, {"name": "Salt and pepper to taste", "description": "Salt and pepper to taste", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "cooking oil", "description": "2/3 tsp cooking oil", "amount": "2/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "garlic fried rice", "description": "1/3 cup garlic fried rice", "amount": "1/3 cup", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC_FRIED_RICE"}, {"name": "egg", "description": "1 egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGG"}]'::jsonb, '[{"title": "Step 1", "description": "Season the fish with salt and pepper."}, {"title": "Step 2", "description": "Heat the oil in a frying pan."}, {"title": "Step 3", "description": "Fry the fish until crispy on both sides."}, {"title": "Step 4", "description": "Remove and drain on paper towels."}, {"title": "Step 5", "description": "Fry the eggs."}, {"title": "Step 6", "description": "Prepare the garlic fried rice."}, {"title": "Step 7", "description": "Serve with vinegar and sliced tomatoes."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginisang Monggo with Rice', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "mung beans (monggo), cooked", "description": "1/1 cup mung beans (monggo), cooked", "amount": "1/1 cup", "market_section": "Vegetable Section", "product_key": "VEG_MUNG_BEANS"}, {"name": "onion, chopped", "description": "1/3 onion, chopped", "amount": "1/3", "market_section": "Vegetable Section", "product_key": "VEG_ONION"}, {"name": "garlic, minced", "description": "1 clove garlic, minced", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "tomato, chopped", "description": "1 tomato, chopped", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_TOMATO"}, {"name": "spinach or malunggay leaves", "description": "1/1 cup spinach or malunggay leaves", "amount": "1/1 cup", "market_section": "Vegetable Section", "product_key": "VEG_SPINACH_MALUNGGAY_LEAVES"}, {"name": "cooking oil", "description": "2/3 tsp cooking oil", "amount": "2/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Salt and pepper to taste", "description": "Salt and pepper to taste", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "steamed rice", "description": "1/3 cup steamed rice", "amount": "1/3 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_STEAMED_RICE"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil and sauté the garlic, onion, and tomatoes."}, {"title": "Step 2", "description": "Add the cooked mung beans and stir well."}, {"title": "Step 3", "description": "Season with salt and pepper."}, {"title": "Step 4", "description": "Simmer for 5 minutes."}, {"title": "Step 5", "description": "Add the spinach or malunggay leaves."}, {"title": "Step 6", "description": "Cook for another 2 minutes."}, {"title": "Step 7", "description": "Serve hot with steamed rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Sardines Omelet', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "sardines in tomato sauce", "description": "1/2 can sardines in tomato sauce", "amount": "1/2 can", "market_section": "Vegetable Section", "product_key": "VEG_SARDINES_TOMATO_SAUCE"}, {"name": "eggs", "description": "2 eggs", "amount": "2", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGGS"}, {"name": "onion, chopped", "description": "1/3 onion, chopped", "amount": "1/3", "market_section": "Vegetable Section", "product_key": "VEG_ONION"}, {"name": "tomato, chopped", "description": "1 tomato, chopped", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_TOMATO"}, {"name": "cooking oil", "description": "2/3 tsp cooking oil", "amount": "2/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Salt and pepper to taste", "description": "Salt and pepper to taste", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}]'::jsonb, '[{"title": "Step 1", "description": "Beat the eggs in a bowl and season with salt and pepper."}, {"title": "Step 2", "description": "Mix in the sardines, onion, and tomato."}, {"title": "Step 3", "description": "Heat oil in a non-stick pan."}, {"title": "Step 4", "description": "Pour the egg mixture into the pan."}, {"title": "Step 5", "description": "Cook until the bottom is set."}, {"title": "Step 6", "description": "Flip carefully and cook the other side until golden. Servings: 1 person"}, {"title": "Step 7", "description": "Serve hot with garlic rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Fried Rice with Salted Egg and Tomatoes', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "cooked rice", "description": "1/3 cup cooked rice", "amount": "1/3 cup", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKED_RICE"}, {"name": "garlic, minced", "description": "1-1 clove garlic, minced", "amount": "1-1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "salted egg, chopped", "description": "1 salted egg, chopped", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALTED_EGG"}, {"name": "tomato, diced", "description": "1 tomato, diced", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_TOMATO"}, {"name": "cooking oil", "description": "2/3 tsp cooking oil", "amount": "2/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "spring onion, chopped", "description": "1 spring onion, chopped", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_SPRING_ONION"}, {"name": "Ground black pepper to taste", "description": "Ground black pepper to taste", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_GROUND_BLACK_PEPPER"}]'::jsonb, '[{"title": "Step 1", "description": "Heat the cooking oil and sauté the garlic until golden."}, {"title": "Step 2", "description": "Add the cooked rice and stir-fry for 3–5 minutes."}, {"title": "Step 3", "description": "Mix in the chopped salted eggs. Servings: 1 person"}, {"title": "Step 4", "description": "Add the diced tomatoes and spring onions."}, {"title": "Step 5", "description": "Season with black pepper."}, {"title": "Step 6", "description": "Stir until everything is evenly combined."}, {"title": "Step 7", "description": "Serve warm as a complete breakfast or alongside grilled meat or fish."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Chorizosilog', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "pieces Vigan longganisa (chorizo)", "description": "2.7 pieces Vigan longganisa (chorizo)", "amount": "2.7", "market_section": "Meat Section", "product_key": "MEAT_PIECES_VIGAN_LONGGANISA"}, {"name": "garlic fried rice", "description": "1/3 cup garlic fried rice", "amount": "1/3 cup", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC_FRIED_RICE"}, {"name": "egg", "description": "1 egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGG"}, {"name": "cooking oil", "description": "1/3 tsp cooking oil", "amount": "1/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Vinegar for dipping", "description": "Vinegar for dipping", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_VINEGAR_FOR_DIPPING"}]'::jsonb, '[{"title": "Step 1", "description": "Place the Vigan longganisa in a frying pan with ¼ cup water."}, {"title": "Step 2", "description": "Cover and cook until the water evaporates. Servings: 1 person"}, {"title": "Step 3", "description": "Add the cooking oil and fry until browned on all sides."}, {"title": "Step 4", "description": "Fry the eggs to your preferred doneness."}, {"title": "Step 5", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 6", "description": "Arrange the longganisa, garlic rice, and egg on a serving plate."}, {"title": "Step 7", "description": "Serve hot with vinegar."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Daing na Bangus Silog', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "marinated boneless bangus", "description": "1 marinated boneless bangus", "amount": "1", "market_section": "Fish Section", "product_key": "FISH_MARINATED_BONELESS_BANGUS"}, {"name": "cooking oil", "description": "2/3 tsp cooking oil", "amount": "2/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "garlic fried rice", "description": "1/3 cup garlic fried rice", "amount": "1/3 cup", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC_FRIED_RICE"}, {"name": "egg", "description": "1 egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGG"}, {"name": "Vinegar for dipping", "description": "Vinegar for dipping", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_VINEGAR_FOR_DIPPING"}]'::jsonb, '[{"title": "Step 1", "description": "Heat the cooking oil over medium heat."}, {"title": "Step 2", "description": "Fry the marinated bangus until golden brown on both sides."}, {"title": "Step 3", "description": "Remove and drain excess oil. Servings: 1 person"}, {"title": "Step 4", "description": "Fry the eggs separately."}, {"title": "Step 5", "description": "Prepare the garlic fried rice."}, {"title": "Step 6", "description": "Arrange the fish, garlic rice, and egg on a serving plate."}, {"title": "Step 7", "description": "Serve with vinegar and sliced tomatoes."}]'::jsonb);
