INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Bistek Silog', 'Breakfast', '40 min', 'Medium', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "beef sirloin, thinly sliced", "description": "500g beef sirloin, thinly sliced", "amount": "500g", "market_section": "Meat Section", "product_key": "MEAT_BEEF_SIRLOIN"}, {"name": "¼ cup soy sauce", "description": "¼ cup soy sauce", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_CUP_SOY_SAUCE"}, {"name": "calamansi juice Servings: 1 person", "description": "3 tbsp calamansi juice Servings: 1 person", "amount": "3 tbsp", "market_section": "Vegetable Section", "product_key": "VEG_CALAMANSI_JUICE_SERVINGS"}, {"name": "large onion, sliced into rings", "description": "1 large onion, sliced into rings", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_LARGE_ONION"}, {"name": "cloves garlic, minced", "description": "4 cloves garlic, minced", "amount": "4", "market_section": "Vegetable Section", "product_key": "VEG_CLOVES_GARLIC"}, {"name": "cooking oil", "description": "2 tbsp cooking oil", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "garlic fried rice", "description": "3 cups garlic fried rice", "amount": "3 cups", "market_section": "Vegetable Section", "product_key": "VEG_CUPS_GARLIC_FRIED"}, {"name": "eggs", "description": "3 eggs", "amount": "3", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGGS"}]'::jsonb, '[{"title": "Step 1", "description": "Marinate the beef in soy sauce, calamansi, and garlic for at least 1 hour."}, {"title": "Step 2", "description": "Fry the beef until browned."}, {"title": "Step 3", "description": "Sauté the onion rings until tender."}, {"title": "Step 4", "description": "Return the beef to the pan and mix with the onions."}, {"title": "Step 5", "description": "Fry the eggs separately."}, {"title": "Step 6", "description": "Prepare the garlic fried rice."}, {"title": "Step 7", "description": "Serve the bistek with garlic rice and fried egg."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginisang Tuna with Rice', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "cans tuna flakes in oil", "description": "2 cans tuna flakes in oil", "amount": "2", "market_section": "Fish Section", "product_key": "FISH_CANS_TUNA_FLAKES"}, {"name": "onion, chopped", "description": "1 onion, chopped", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_ONION"}, {"name": "cloves garlic, minced", "description": "3 cloves garlic, minced", "amount": "3", "market_section": "Vegetable Section", "product_key": "VEG_CLOVES_GARLIC"}, {"name": "tomatoes, chopped Servings: 1 person", "description": "2 tomatoes, chopped Servings: 1 person", "amount": "2", "market_section": "Vegetable Section", "product_key": "VEG_TOMATOES"}, {"name": "cooking oil", "description": "2 tbsp cooking oil", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Salt and pepper to taste", "description": "Salt and pepper to taste", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "steamed rice", "description": "3 cups steamed rice", "amount": "3 cups", "market_section": "Dry Goods / Condiments", "product_key": "DRY_CUPS_STEAMED_RICE"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil and sauté the garlic and onion."}, {"title": "Step 2", "description": "Add the tomatoes and cook until soft."}, {"title": "Step 3", "description": "Stir in the tuna flakes."}, {"title": "Step 4", "description": "Season with salt and pepper."}, {"title": "Step 5", "description": "Cook for another 3–5 minutes."}, {"title": "Step 6", "description": "Serve over warm rice."}, {"title": "Step 7", "description": "Enjoy immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pork Giniling Silog', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "ground pork", "description": "500g ground pork", "amount": "500g", "market_section": "Meat Section", "product_key": "MEAT_GROUND_PORK"}, {"name": "onion, chopped", "description": "1 onion, chopped", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_ONION"}, {"name": "cloves garlic, minced Servings: 1 person", "description": "3 cloves garlic, minced Servings: 1 person", "amount": "3", "market_section": "Vegetable Section", "product_key": "VEG_CLOVES_GARLIC"}, {"name": "tomatoes, chopped", "description": "2 tomatoes, chopped", "amount": "2", "market_section": "Vegetable Section", "product_key": "VEG_TOMATOES"}, {"name": "½ cup diced carrots", "description": "½ cup diced carrots", "amount": "1 serving", "market_section": "Vegetable Section", "product_key": "VEG_CUP_DICED_CARROTS"}, {"name": "½ cup green peas", "description": "½ cup green peas", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_CUP_GREEN_PEAS"}, {"name": "soy sauce", "description": "2 tbsp soy sauce", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "cooking oil", "description": "2 tbsp cooking oil", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "garlic fried rice", "description": "3 cups garlic fried rice", "amount": "3 cups", "market_section": "Vegetable Section", "product_key": "VEG_CUPS_GARLIC_FRIED"}, {"name": "eggs", "description": "3 eggs", "amount": "3", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGGS"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil and sauté the garlic, onion, and tomatoes."}, {"title": "Step 2", "description": "Add the ground pork and cook until browned."}, {"title": "Step 3", "description": "Stir in the carrots, peas, and soy sauce."}, {"title": "Step 4", "description": "Simmer until the vegetables are tender."}, {"title": "Step 5", "description": "Fry the eggs separately."}, {"title": "Step 6", "description": "Prepare the garlic fried rice."}, {"title": "Step 7", "description": "Serve hot."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Chicken Omelet with Garlic Rice', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '600 kcal', 4292932350, '[{"name": "cooked shredded chicken", "description": "2 cups cooked shredded chicken", "amount": "2 cups", "market_section": "Meat Section", "product_key": "MEAT_CUPS_COOKED_SHREDDED"}, {"name": "eggs Servings: 1 person", "description": "4 eggs Servings: 1 person", "amount": "4", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGGS_SERVINGS_PERSON"}, {"name": "onion, chopped", "description": "1 onion, chopped", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_ONION"}, {"name": "½ bell pepper, diced", "description": "½ bell pepper, diced", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_BELL_PEPPER"}, {"name": "cooking oil", "description": "2 tbsp cooking oil", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Salt and pepper to taste", "description": "Salt and pepper to taste", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "garlic fried rice", "description": "3 cups garlic fried rice", "amount": "3 cups", "market_section": "Vegetable Section", "product_key": "VEG_CUPS_GARLIC_FRIED"}]'::jsonb, '[{"title": "Step 1", "description": "Beat the eggs and season with salt and pepper."}, {"title": "Step 2", "description": "Sauté the onion and bell pepper until soft."}, {"title": "Step 3", "description": "Add the shredded chicken and cook for 2 minutes."}, {"title": "Step 4", "description": "Pour in the beaten eggs."}, {"title": "Step 5", "description": "Cook until set, then fold the omelet in half."}, {"title": "Step 6", "description": "Prepare the garlic fried rice."}, {"title": "Step 7", "description": "Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pancit Canton', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '350 kcal', 4292932350, '[{"name": "pancit canton noodles", "description": "28g pancit canton noodles", "amount": "28g", "market_section": "Dry Goods / Condiments", "product_key": "DRY_PANCIT_CANTON_NOODLES"}, {"name": "chicken breast, sliced", "description": "33g chicken breast, sliced", "amount": "33g", "market_section": "Meat Section", "product_key": "MEAT_CHICKEN_BREAST"}, {"name": "cabbage, shredded, shredded", "description": "1/1 cup cabbage, shredded, shredded", "amount": "1/1 cup", "market_section": "Vegetable Section", "product_key": "VEG_CABBAGE"}, {"name": "carrot, julienned", "description": "1/3 carrot, julienned", "amount": "1/3", "market_section": "Vegetable Section", "product_key": "VEG_CARROT"}, {"name": "garlic, minced", "description": "1 clove garlic, minced", "amount": "1 clove", "market_section": "Vegetable Section", "product_key": "VEG_GARLIC"}, {"name": "onion, sliced", "description": "1/3 onion, sliced", "amount": "1/3", "market_section": "Vegetable Section", "product_key": "VEG_ONION"}, {"name": "soy sauce", "description": "2/3 tsp soy sauce", "amount": "2/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SOY_SAUCE"}, {"name": "cooking oil", "description": "2/3 tsp cooking oil", "amount": "2/3 tsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "egg", "description": "1 egg", "amount": "1", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGG"}, {"name": "pieces pandesal", "description": "2/3 pieces pandesal", "amount": "2/3", "market_section": "Dry Goods / Condiments", "product_key": "DRY_PIECES_PANDESAL"}]'::jsonb, '[{"title": "Step 1", "description": "Cook the pancit canton noodles according to the package directions and drain."}, {"title": "Step 2", "description": "Heat the oil and sauté the garlic and onion until fragrant."}, {"title": "Step 3", "description": "Add the chicken and cook until lightly browned."}, {"title": "Step 4", "description": "Stir in the cabbage and carrots, then cook until tender."}, {"title": "Step 5", "description": "Add the noodles and soy sauce, tossing until evenly coated."}, {"title": "Step 6", "description": "Fry the eggs separately and toast the pandesal."}, {"title": "Step 7", "description": "Serve the pancit canton with a fried egg and toasted pandesal."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tortang Dilis', 'Breakfast', '40 min', 'Easy', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=400&h=250&fit=crop', '1 serving', '350 kcal', 4292932350, '[{"name": "dried dilis (anchovies)", "description": "1 cup dried dilis (anchovies)", "amount": "1 cup", "market_section": "Fish Section", "product_key": "FISH_DRIED_DILIS"}, {"name": "eggs", "description": "4 eggs", "amount": "4", "market_section": "Dry Goods / Condiments", "product_key": "DRY_EGGS"}, {"name": "onion, chopped", "description": "1 onion, chopped", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_ONION"}, {"name": "tomato, chopped", "description": "1 tomato, chopped", "amount": "1", "market_section": "Vegetable Section", "product_key": "VEG_TOMATO"}, {"name": "cooking oil", "description": "2 tbsp cooking oil", "amount": "2 tbsp", "market_section": "Dry Goods / Condiments", "product_key": "DRY_COOKING_OIL"}, {"name": "Salt and pepper to taste", "description": "Salt and pepper to taste", "amount": "1 serving", "market_section": "Dry Goods / Condiments", "product_key": "DRY_SALT_AND_PEPPER"}, {"name": "steamed rice", "description": "3 cups steamed rice", "amount": "3 cups", "market_section": "Dry Goods / Condiments", "product_key": "DRY_CUPS_STEAMED_RICE"}]'::jsonb, '[{"title": "Step 1", "description": "Rinse the dried anchovies quickly and pat dry."}, {"title": "Step 2", "description": "Beat the eggs and mix in the onion and tomato."}, {"title": "Step 3", "description": "Stir in the dried anchovies."}, {"title": "Step 4", "description": "Heat the oil in a non-stick pan."}, {"title": "Step 5", "description": "Pour in the egg mixture and cook until golden on the bottom."}, {"title": "Step 6", "description": "Flip carefully and cook the other side until fully set."}, {"title": "Step 7", "description": "Serve hot with steamed rice."}]'::jsonb);